INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(3801, 'koKR', 'Dziedzictwo Czarnorytych', 'Witaj, $N. Jestem Franclorn Kuźnomistrz. Tak, ten sam Franclorn Kuźnomistrz, twórca kamiennokutej metody budowania. Podczas swoich wędrówek po naszym rozdartym wojną świecie z pewnością $gprzechodziłeś:przechodziłaś; przez któreś z moich dzieł albo na nim $gstałeś:stałaś;.$B$BZapewne zastanawiasz się, dlaczego tu jestem i czego od ciebie chcę – oba pytania są zasadne.$B$BPotrzebuję twojej pomocy, rzecz jasna. W zamian dam ci klucz do głębin mojego przeklętego miasta.', 'Jeśli chcesz zdobyć klucz do głównego miasta, porozmawiaj z Franclornem Kuźnomistrzem w Grobowcu Kuźnomistrza w Czarnej Górze.', '', '', '', '', '', '', 0),
(3802, 'koKR', 'Dziedzictwo Czarnorytych', 'Fineousa Mrokowija znajdziesz za Kręgiem Prawa, w Sali Rzemiosła. Zabij tego nędznego kundla i odzyskaj Żelazospacza.$B$BZanieś Żelazospacza do Kaplicy Thaurissana i umieść młot tam, gdzie jego miejsce: w dłoniach posągu wzniesionego na moją cześć.$B$BGdy to zrobisz, otworzy się skrytka, w której ukryłem klucz główny. Co ważniejsze, Żelazospacz na zawsze pozostanie w moim uścisku. Jeśli spróbują wyjąć młot, zarówno posąg, jak i młot roztrzaskają się i przepadną na zawsze.', 'Zabij Fineousa Mrokowija i odzyskaj wielki młot Żelazospacza. Zanieś go do Kaplicy Thaurissana i umieść na posągu Franclorna Kuźnomistrza.$B', '', 'Odszukaj pomnik Franclorna Kuźnomistrza w Kaplicy Thaurissana w Otchłani Czarnej Góry.', '', '', '', '', 0),
(3823, 'koKR', 'Zgasić Ogniste Trzewia', 'Musimy uderzyć na wrogów, zanim oni uderzą na nas!$B$BBędę się streszczał, żołnierzu.$B$BOgry z Ognistych Trzewi na Płonących Stepach są sojusznikami orków Czarnej Skały. Blisko współpracują z tymi plugawymi orkami: pilnują bogatej w minerały Skały Upiornych Maczug i przez cały czas utrzymują otwarte szlaki zaopatrzenia.$B$BZostaw po sobie ślad, $N. Okalecz ich siły i wróć do mnie, gdy robota będzie skończona.$B$B<Oralius chwyta powietrze i wykonuje ruch, jakby kogoś dusił.>$B$BZABIJĘ CIĘ, WINKY!', 'Zabij 15 ogrów magów z Ognistych Trzewi, 7 ogrów z Ognistych Trzewi i 7 osiłków z Ognistych Trzewi.', '', 'Wróć do Oraliusa w Czuwaniu Morgana na Płonących Stepach.', '', '', '', '', 0),
(3824, 'koKR', 'Gor\'tesh, pan osiłków', 'Mówię ci, oni się chwieją! Nasze następne uderzenie musi być decydujące.$B$BPan osiłków, Gor\'tesh, musi zginąć. Co ważniejsze, jego głowa musi trafić do mnie, żebym mógł przygotować trzecią fazę naszego ataku na ogry z Ognistych Trzewi.$B$BUważaj, żołnierzu: Gor\'tesh nie rządzi ze Skały Upiornych Maczug, lecz z budowli orków Czarnej Skały na zachód od niej.$B$BTwoje rozkazy są więc proste. Znajdź Gor\'tesha i odrąb mu ten tłusty łeb. Wróć do mnie, gdy robota będzie skończona.$B$BZAMKNIJ SIĘ, WINKY!', 'Zdobądź odrąbaną głowę Gor\'tesha.$B', '', 'Wróć do Oraliusa w Czuwaniu Morgana na Płonących Stepach.', '', '', '', '', 0),
(3825, 'koKR', 'Ogrzy łeb na palu = impreza', 'Zostało ci tylko jedno, żołnierzu.$B$BPozwoliłem sobie nabić głowę Gor\'tesha na pal. Teraz wystarczy, że zaniesiesz ją na szczyt Skały Upiornych Maczug i wbijesz w ziemię. Gdy to zrobisz, patrz, jak te tchórzliwe ogry uciekają, gdzie pieprz rośnie! Kiedy już się nacieszysz, wróć do mnie, a nagrodzę cię za cały twój trud.$B$B<Oralius zdaje się tracić kontakt z rzeczywistością.>', 'Zanieś odrąbaną głowę Gor\'tesha na szczyt Skały Upiornych Maczug i ją tam umieść. Poszukaj kopczyka miękkiej ziemi, w który wbijesz pal.', '', 'Wróć do Oraliusa w Czuwaniu Morgana na Płonących Stepach.', 'Głowa Gor\'tesha zatknięta', '', '', '', 0),
(4022, 'koKR', 'Smak płomienia', 'Stado wie o twoich czynach w Płonącym Wąwozie.$B$BPokaż mi ją, $gśmiertelniku:śmiertelniczko;. Wylinkę, $gimbecylu:imbecylko;.', 'Pokaż Cyrusowi Therepentousowi wylinkę Czarnego Stada, którą $gotrzymałeś:otrzymałaś; od Kalarana Wietrznego Ostrza.$B', 'Dowód przedstawiony', 'Porozmawiaj z Cyrusem Therepentousem przy Skale Pełzaczy na Płonących Stepach.', '', '', '', '', 0),
(4023, 'koKR', 'Smak płomienia', 'Szukasz Stada? Przedstaw mi dowód swojej wartości, $gśmiertelniku:śmiertelniczko;.', 'Przedstaw Cyrusowi Therepentousowi dowód swojej wartości.$B$BMasz przeczucie, że Cyrus już wie, że nie jesteś $ggodzien:godna;.', '', 'Wróć do Cyrusa Therepentousa przy Skale Pełzaczy na Płonących Stepach.', '', '', '', '', 0),
(4024, 'koKR', 'Smak płomienia', 'Pragnę zakosztować palących płomieni ognistej góry. Pozwolić, by roztopione ognie Czarnej Góry spłynęły kaskadą po mojej istocie. Ta esencja, ten palący żar – tego łaknę.$B$BW Otchłani Czarnej Góry przebywa Bael\'Gar: istota z czystego płomienia, zrodzona z ognia Ragnarosa. Zabij Bael\'Gara i z jego tlących się szczątków przynieś mi cząstkę jego wewnętrznego ognia.$B$BUżyj wylinki na jego szczątkach, by bezpiecznie wydobyć wewnętrzny płomień.$B$BUda ci się – zostaniesz $gnagrodzony:nagrodzona;.', 'Udaj się do Otchłani Czarnej Góry i zabij Bael\'Gara.$B$BWiesz tylko tyle, że olbrzym przebywa w Otchłani Czarnej Góry. Pamiętaj, by użyć zmienionej wylinki Czarnego Stada na szczątkach Bael\'Gara i schwytać ognistą esencję.$B$BZanieś zamkniętą ognistą esencję Cyrusowi Therepentousowi.$B', '', 'Wróć do Cyrusa Therepentousa przy Skale Pełzaczy na Płonących Stepach.', '', '', '', '', 0),
(4123, 'koKR', 'Serce góry', 'Od lat szukam pewnego klejnotu. Nazywa się Serce góry i jest wielki jak twoja pięść! Czarnoryci trzymają go zamkniętego w swoim skarbcu i choćbym nie wiem jak się starał, nie chcą mi go sprzedać.$B$BMuszę więc uciec się do siły.$B$BPrzebij się do Dolnego Skarbca w Otchłani Czarnej Góry, rozpracuj jego tajny sejf i zdobądź Serce. W tym celu musisz pokonać Strażnika Zgubochwyta, a on nie pojawi się, dopóki nie otworzysz wszystkich skrzyń z relikwiami w skarbcu!$B$BPowodzenia.', 'Zanieś Serce góry Maxwortowi Uberglintowi na Płonących Stepach.', '', 'Wróć do Maxworta Uberglinta na Płonących Stepach.', '', '', '', '', 0),
(4136, 'koKR', 'Ribbly Śrubokran', 'Mój brat Ribbly zawsze był utrapieniem rodziny: brał nasze pieniądze i trwonił je na jeden szalony plan po drugim.$B$BCóż, jego ostatni plan musiał być najgorszy, bo baron Revilgaz z Łupieżczej Zatoki właśnie wyznaczył nagrodę za głowę biednego Ribbly\'ego. Nie masz pojęcia, jak to ucieszyło Śrubokranów! Nasz mały Ribbly w końcu jest coś wart!$B$BTylko że teraz ukrywa się głęboko w Otchłani Czarnej Góry. Proszę, znajdź go i przyprowadź do mnie!$B$BA jeśli nie zechce przyjść, to nic... po prostu przynieś mi jego głowę.', 'Zanieś głowę Ribbly\'ego Yuce Śrubokran na Płonących Stepach.', '', 'Wróć do Yuki Śrubokran na Płonących Stepach.', '', '', '', '', 0),
(4182, 'koKR', 'Smocze zagrożenie', 'Życie na Płonących Stepach obfituje w konflikty.$B$BTylko spójrz na to miejsce! Niewiele wiemy o tym, co się stało z tymi budynkami, ale wiemy, że kiedyś, przed wielkim wybuchem, wszystko to było częścią pasma Gór Rudej Grani.$B$BDość lamentów! Mamy problem, $N. Być może $gzauważyłeś:zauważyłaś; smoczy pomiot pod tym grzbietem. Potrzebujemy pomocy, by go odeprzeć. Zabij, ile zdołasz, i wróć do mnie. Uda ci się – wtedy może porozmawiamy o innych sprawach.$B', 'Zabij 15 czarnych smoczych młodych, 10 czarnych smoczych pomiotów, 4 czarnych smokorodnych i 1 czarnego smokowca.', '', 'Wróć do Helendisa Rzecznego Roga w Czuwaniu Morgana na Płonących Stepach.', '', '', '', '', 0),
(4183, 'koKR', 'Prawdziwi panowie', 'Zawsze zakładaliśmy, że orkowie Czarnej Skały są wytworem swojego dzikiego wychowania. To, co znaleźliśmy tutaj, w ich ojczyźnie, mówi nam co innego.$B$BTo prawda, siłę daje im żądza krwi i pragnienie walki, ale orkami Czarnej Skały władają istoty z Czarnego Stada. Podejrzewamy, że to Czarne Stado podsyca w nich wściekłość i wrogość.$B$BZanieś ten list sędziemu Solomonowi. On będzie wiedział, co należy zrobić.$B$B<Helendis podaje ci zapieczętowany list.>', 'Udaj się do Jeziernych Włości w Górach Rudej Grani i doręcz list Helendisa Rzecznego Roga sędziemu Solomonowi.', '', '', '', '', '', '', 0),
(4184, 'koKR', 'Prawdziwi panowie', 'To ponure wieści, $N. Odkrycie, że nasi śmiertelni wrogowie są jedynie pionkami znacznie większego zagrożenia, odbiera ducha. Jezierne Włości w żaden sposób nie przetrwają ataku zarówno orków Czarnej Skały, jak i Czarnego Stada. Jeśli Jezierne Włości padną, następne będą Mroczne Włości, a potem co? Złote Włości? Sam Wichrogród?$B$BMusisz natychmiast przekazać te informacje królowi Varianowi Wrynnowi w Wichrogrodzie! Jeśli to nie zasługuje na pomoc Wichrogrodu, to nic na nią nie zasługuje i wszystko stracone.$B', 'Udaj się do Wichrogrodu i doręcz prośbę Solomona królowi Varianowi Wrynnowi.$B$BKról Varian Wrynn rezyduje w Twierdzy Wichrogród.', '', '', '', '', '', '', 0),
(4185, 'koKR', 'Prawdziwi panowie', 'Solomon maluje ponury obraz. Mimo to nie możemy sobie pozwolić na wysłanie naszych rozproszonych wojsk na pomoc Jeziernym Włościom na podstawie domysłów. Zanim zacznę działać, będę potrzebował dowodów na te twierdzenia.$B$BPorozmawiaj z lady Prestor, $N. To uczona kobieta, która wie wiele o smokach i smoczym pomiocie. Może zdoła rzucić nieco światła na tę sytuację.$B', 'Po rozmowie z lady Katraną Prestor porozmawiaj z najwyższym lordem Bolvarem Fordragonem.', 'Rada lady Prestor', '', '', '', '', '', 0),
(4186, 'koKR', 'Prawdziwi panowie', 'Mianuję cię pełniącym obowiązki zastępcą Wichrogrodu, $N.$B$BWróć do sędziego Solomona w Jeziernych Włościach i doręcz mu ten dekret.', 'Zanieś dekret Wrynna sędziemu Solomonowi w Jeziernych Włościach.$B', '', '', '', '', '', '', 0),
(4223, 'koKR', 'Prawdziwi panowie', '<Sędzia Solomon wzdycha.>$B$BMusisz wrócić na Płonące Stepy, $N. Jako zastępca Wichrogrodu będziesz $gmusiał:musiała; zameldować się u marszałka Maxwella. Powodzenia.', 'Porozmawiaj z marszałkiem Maxwellem na Płonących Stepach.', '', '', '', '', '', '', 0),
(4224, 'koKR', 'Prawdziwi panowie', 'Co? $GMyślałeś:Myślałaś;, że jesteś $gpierwszy:pierwsza;? Ilu żołnierzy musimy stracić, zanim Wichrogród zacznie działać?$B$BZgromadziliśmy ogromne ilości informacji o zagrożeniu ze strony Czarnej Skały, zanim straciliśmy naszego dowódcę, marszałka Windsora. Wraz z marszałkiem Windsorem przepadły wszystkie nasze cenne informacje.$B$BPotrzebujemy tych dokumentów. Porozmawiaj z Obdartym Johnem, $N. Był z Windsorem, gdy zaatakował ich oddział najeźdźców z Czarnej Skały. Ostatnio widziano go w jaskini na północy.', 'Porozmawiaj z Obdartym Johnem.', 'Opowieść Obdartego Johna', 'Wróć do marszałka Maxwella w Czuwaniu Morgana na Płonących Stepach.', '', '', '', '', 0),
(4262, 'koKR', 'Nadmistrz Pyron', 'Ostatnia piątka moich magów, którzy węszyli w Czarnej Górze, wróciła mocno przypieczona, z trwałą pomarańczową gnomią fryzurą afro – albo i gorzej.$B$B<Jalinda podnosi z ziemi garść popiołu i wypuszcza go w powietrze.>$B$BSzczególnie jeden paskudny drań, Nadmistrz Pyron, sprawia sporo kłopotów. Trzeba zlikwidować tego żywiołaka, żeby nasza ekipa ekspedycyjna mogła się przedostać do Otchłani Czarnej Góry!$B$BPilnuje wejścia przy Kamieniołomie Czarnej Skały.', 'Zabij Nadmistrza Pyrona.$B$BPamiętasz, że Jalinda mówiła, iż Pyron strzeże kamieniołomu. Może tam warto poszukać?', '', 'Wróć do Jalindy Sprig w Czuwaniu Morgana na Płonących Stepach.', '', '', '', '', 0),
(4263, 'koKR', 'Incendius!', 'Na pewno Pyron powiedział „Incendius”, kiedy umierał?$B$B<Jalinda z trudem przełyka ślinę.>$B$BPodobno lord Incendius jest sługą Ragnarosa! O rety, o rety... co my teraz zrobimy?$B$BDasz radę podjąć się kolejnej misji? Nie mam nikogo innego, kogo mogłabym wysłać, $N!$B$BNigdy nie wprowadzimy tam drużyny, jeśli Incendius będzie wciąż wskrzeszał Pyrona z popiołów.$B$BMusisz odnaleźć i zniszczyć lorda Incendiusa!$B', 'Odnajdź lorda Incendiusa w Otchłani Czarnej Góry i zniszcz go!', '', 'Wróć do Jalindy Sprig w Czuwaniu Morgana na Płonących Stepach.', '', '', '', '', 0),
(4283, 'koKR', 'PIĘĆDZIESIĄT! TAK JEST!', 'Zdradzę ci mały sekret, żołnierzu. Podejdź no bliżej.$B$BJESTEM TU JEDYNYM NORMALNYM!$B$BSpójrz na tych ludzi! Uwierzysz, że wszyscy są szaleni!? A są! ŚWIRY! WARIACI!$B$B<Oralius ścisza głos.>$B$BNiech to zostanie między mną, tobą i moim kumplem kapitanem Winkym.$B$B<Oralius chwyta powietrze i ściska.>$B$BTaaaaak czy siak... Zbieram odznaki do kompletu z moją kolekcją ogrzych uszu. Dziś w menu orki. Pięćdziesiąt. RUSZAJ!$B$B<Oralius dmie w róg.>$B$BJAZDA!', 'Zbierz 50 medalionów Czarnej Skały.', '', 'Wróć do Oraliusa w Czuwaniu Morgana na Płonących Stepach.', '', '', '', '', 0),
(4286, 'koKR', 'Dobry towar', 'Kapitan Winky mówi mi, że Czarnoryci w Otchłani mają cały najlepszy towar. Nie, Winky?$B$B<Oralius ze wszystkich sił udaje pirata.>$B$BARRR, KAMRATKU! TAK JEST!$B$BWidzisz, o czym mówię? Musisz tam wejść i przynieść mi próbki dobrego towaru.$B$BWłaź tam i pokaż, co potrafisz!$B', 'Zbierz 20 nerek Czarnorytych.', '', 'Wróć do Oraliusa w Czuwaniu Morgana na Płonących Stepach.', '', '', '', '', 0),
(4296, 'koKR', 'Tablica Siedmiu', 'Przybyłem na Płonące Stepy śladem legend o Siedmiu. Byli to krasnoludowie wielkiej wiedzy i potęgi, a gdzie wiedza i potęga, tam i bogactwo.$B$BTego właśnie chcę. Bogactwa!$B$BJeśli dowiemy się więcej o Siedmiu, może razem się wzbogacimy. Podobno w ruinach Thaurissana przechowywana jest Tablica Siedmiu, zawierająca wiedzę starożytnych krasnoludów. Znajdź tę tablicę, przepisz jej tekst i przynieś mi go. Odkryjmy razem jej tajemnice!', 'Zdobądź odpis tablicy.', '', 'Wróć do Maxworta Uberglinta na Płomiennym Grzbiecie na Płonących Stepach.', '', '', '', '', 0),
(4463, 'koKR', 'Libram rozmyślań', '', '', '', 'Wróć do Mathredisa Ognistej Gwiazdy na Płomiennym Grzbiecie na Płonących Stepach.', '', '', '', '', 0),
(4481, 'koKR', 'Libram kondycji', '', '', '', 'Wróć do Mathredisa Ognistej Gwiazdy na Płomiennym Grzbiecie na Płonących Stepach.', '', '', '', '', 0),
(4482, 'koKR', 'Libram nieustępliwości', '', '', '', 'Wróć do Mathredisa Ognistej Gwiazdy na Płomiennym Grzbiecie na Płonących Stepach.', '', '', '', '', 0),
(4483, 'koKR', 'Libram odporności', '', '', '', 'Wróć do Mathredisa Ognistej Gwiazdy na Płomiennym Grzbiecie na Płonących Stepach.', '', '', '', '', 0),
(4484, 'koKR', 'Libram żarłoczności', '', '', '', 'Wróć do Mathredisa Ognistej Gwiazdy na Płomiennym Grzbiecie na Płonących Stepach.', '', '', '', '', 0),
(4701, 'koKR', 'Uśpić ją', 'Z pewnością $gwidziałeś:widziałaś; worgi, którymi dowodzą orkowie Czarnej Skały.$B$BTo ciekawe – bez względu na to, ile ich zabijemy, wcale ich nie ubywa. Moi zwiadowcy donoszą, że worgi są hodowane, szkolone i ostatecznie wysyłane z Iglicy Czarnej Góry – stolicy orków Czarnej Skały. Musisz udać się do Iglicy Czarnej Góry i odkryć źródło tego zagrożenia. Odkryć... i zniszczyć.$B$BPowodzenia, $N. Niech Cenarius cię chroni...$B', 'Udaj się do Iglicy Czarnej Góry i zniszcz źródło zagrożenia ze strony worgów. Gdy $godchodziłeś:odchodziłaś; od Helendisa, wykrzyczał za tobą imię: Halycon. Tak orkowie nazywają worga.', '', 'Wróć do Helendisa Rzecznego Roga w Czuwaniu Morgana na Płonących Stepach.', '', '', '', '', 0),
(4726, 'koKR', 'Esencja smoczego młodego', 'Od tygodni badam smoczy pomiot na Płonących Stepach i chyba w końcu dokonałam przełomu! Stworzyłam urządzenie – nazywam je Smoko-Inkarcynatrix 900. Potrafi schwytać esencję smoczych młodych!$B$BA przynajmniej tak mi się wydaje.$B$BMasz, weź urządzenie i potraktuj nim jakieś smocze młode na Płonących Stepach. Gdy będzie pod działaniem urządzenia, pokonaj je, a jego esencja powinna się uwolnić.$B$BJeśli tak się stanie, to wspaniale! Przynieś mi próbki, żebym mogła je zbadać!', 'Zanieś 8 esencji smoczego młodego i Smoko-Inkarcynatrix 900 Tinkee Parowar na Płomiennym Grzbiecie na Płonących Stepach.', '', 'Wróć do Tinkee Parowar na Płomiennym Grzbiecie na Płonących Stepach.', '', '', '', '', 0),
(4729, 'koKR', 'Egzotyczne zwierzaki Kiblera', 'Pewnie się zastanawiasz, co ja tu robię. Spójrz na te klatki! Czy to nie oczywiste?$B$BPrzede wszystkim kocham zwierzęta, ale z zawodu jestem handlarzem. Wyszukuję egzotyczne zwierzęta dla bogatych i sławnych i oswajam te bestie, żeby zachowywały się jak porządne zwierzaki.$B$BTeraz pewnie się zastanawiasz: „Co mogę dla ciebie zrobić, Kibler?”. Odpowiedź jest prosta: weź tę klatkę na bestie i znajdź mi kilka szczeniąt worga. W zamian oswoję dla ciebie worga!$B', 'Udaj się do Iglicy Czarnej Góry i znajdź szczenięta worga Krwawego Topora. Użyj klatki, by przenieść te dzikie maleństwa. Przynieś Kiblerowi szczenię worga w klatce.', '', 'Wróć do Kiblera na Płomiennym Grzbiecie na Płonących Stepach.', '', '', '', '', 0),
(4734, 'koKR', 'Zamrażanie jaj', '$N, ciężko pracuję nad nowym urządzeniem – jajoscyloskopem! Ma wystrzeliwać impuls zimnej energii w jajo czarnego smoka... i zamrażać je na kość! Możesz go dla mnie przetestować?$B$BSłyszałam, że wysoko w Iglicy Czarnej Góry smoki mają wylęgarnię, gdzie wysiadują jaja. Tam musisz się udać, żeby przetestować jajoscyloskop, a potem daj mi znać, jak zadziałał!$B$BI nie martw się. Zamrożone smocze jaja powinny być nieszkodliwe. To te niezamrożone są groźne!', 'Użyj prototypu jajoscyloskopu na jaju w Wylęgarni w Iglicy Czarnej Góry.', 'Przetestuj prototyp jajoscyloskopu', 'Wróć do Tinkee Parowar na Płomiennym Grzbiecie na Płonących Stepach.', '', '', '', '', 0),
(4735, 'koKR', 'Zbieranie jaj', '$N, w końcu jestem gotowa na prawdziwe próbki smoczych jaj! Masz, weź ten moduł kolektroniczny. Służy do wydobywania smoczych jaj i przygotowania ich do transportu. Wróć do Wylęgarni i użyj modułu, by zebrać jaja.$B$BI nie zapomnij ich najpierw zamrozić, bo mogą się wykluć, zanim je zbierzesz!$B$BGdy będziesz mieć dość jaj, przynieś mi je!', 'Zanieś 8 zebranych smoczych jaj i moduł kolektroniczny Tinkee Parowar na Płomiennym Grzbiecie na Płonących Stepach.', '', 'Wróć do Tinkee Parowar na Płomiennym Grzbiecie na Płonących Stepach.', '', '', '', '', 0),
(4764, 'koKR', 'Klamra Doomriggera', 'Wysoko w Iglicy Czarnej Góry znajduje się komnata, którą niegdyś nazywano Salą Fortuny. Czarnoryci trzymali w niej swoje relikwie, trofea i dzieła sztuki.$B$BTo było dawno temu. Podobno sala się zawaliła i teraz służy do... mniej przyjemnych celów. Wierzę jednak, że wciąż można tam znaleźć jakieś stare krasnoludzkie relikwie.$B$BJedną z nich jest klamra Doomriggera, której powierzchnia jest tak gęsto wysadzana rzadkimi klejnotami, że podobno każdy krasnolud, który na nią spojrzy, zalewa się łzami.$B$BTa klamra, $N, jest twoim celem.', 'Zanieś klamrę Doomriggera Mayarze Jasnoskrzydłej na Płonących Stepach.', '', 'Wróć do Mayary Jasnoskrzydłej w Czuwaniu Morgana na Płonących Stepach.', '', '', '', '', 0),
(4808, 'koKR', 'Felnok Stalosprężyn', 'Mam do ciebie jeszcze jedną prośbę.$B$BWstępne badania zebranej przez ciebie esencji wykazały, że być może da się zamrażać jaja smoczych piskląt i je konserwować! Chcę sprawdzić tę teorię, ale najpierw potrzebuję specjalnie wykonanych części inżynieryjnych. Może je zrobić mój kolega, Felnok Stalosprężyn.$B$BMasz, zanieś ten list Felnokowi. Jest w nim, czego potrzebuję. Felnoka znajdziesz w Zimozdroju, w mieście Wiecznowid.', 'Oddaj list Tinkee Felnokowi Stalosprężynowi w Wiecznowidzie w Zimozdroju.', '', '', '', '', '', '', 0),
(4810, 'koKR', 'Powrót do Tinkee', 'Dobra, wszystko przygotowane, spakowane i gotowe do transportu! Powodzenia w podróży i koniecznie powiedz Tinkee, że ma u mnie dług!', 'Zanieś paczkę Felnoka Tinkee Parowar na Płomiennym Grzbiecie na Płonących Stepach.', '', '', '', '', '', '', 0),
(4862, 'koKR', 'Pe-A-Es-Ka-U-De-A', 'Wierz lub nie, ale są ludzie gotowi płacić nawet za najobrzydliwsze oswojone bestie!$B$BWysłałem Bijou do Iglicy, żeby zebrała trochę jaj pająków z Iglicy, ale od tygodni nie mam od niej wieści. Może ty mi pomożesz?$B$BPowiem ci tak, $N. Idź do Iglicy Czarnej Góry i zbierz dla mnie trochę jaj pająków z Iglicy. Przynieś je tutaj, a nie tylko dam ci trochę grosza, ale jeszcze oswoję jednego dla ciebie!', 'Udaj się do Iglicy Czarnej Góry i zbierz 15 jaj pająków z Iglicy dla Kiblera.$B$BSądząc po nazwie, te jaja można znaleźć w pobliżu pająków.$B', '', 'Wróć do Kiblera na Płomiennym Grzbiecie na Płonących Stepach.', '', '', '', '', 0),
(4866, 'koKR', 'Matczyne mleko', 'To chyba jedna z najsilniejszych trucizn na świecie, $N!$B$BPodczas wypadów do Iglicy podsłuchałem, jak ci z Czarnej Skały mówią o jej zabójczości. Nazywają ją „Matczynym mlekiem”, od Matki Tlącosieć, wielkiej paskudnej pajęczycy z jaskini Pajęczej Sieci.$B$BA teraz posłuchaj, czego od ciebie potrzebuję: żywej próbki Mleka, płynącej w TWOICH żyłach. Samo przyniesienie gruczołu nie wystarczy! Niech cię otruje, a potem wróć do mnie!$B$BWtedy... będę mógł cię wydoić!$B$B<Zaciera ręce w oczekiwaniu.>', 'W sercu Iglicy Czarnej Góry znajdziesz Matkę Tlącosieć. Zaatakuj ją i daj się otruć. Najpewniej będziesz też $gmusiał:musiała; ją zabić. Gdy już zostaniesz $gotruty:otruta;, wróć do Obdartego Johna, żeby mógł cię „wydoić”.', 'Wydojono', 'Wróć do Obdartego Johna na Płomiennym Grzbiecie na Płonących Stepach.', '', '', '', '', 0),
(4907, 'koKR', 'Tinkee Parowar', 'Cześć, $N. Pamiętasz Tinkee Parowar? Cóż, ona pamięta ciebie! Przysłała mi wiadomość, żebym wypatrywał, czy się nie pojawisz, bo... znów potrzebuje twojej pomocy. Chyba ma to coś wspólnego z jej badaniami nad smokami.$B$B$GPowinieneś:Powinnaś; z nią porozmawiać na Płonących Stepach, na Płomiennym Grzbiecie.', 'Porozmawiaj z Tinkee Parowar na Płomiennym Grzbiecie na Płonących Stepach.', '', '', '', '', '', '', 0),
(5002, 'koKR', 'Wiadomość dla Maxwella', 'Jestem goblinką, która dotrzymuje słowa. A teraz słuchaj uważnie:$B$BTych orków używa się głównie jako zwierząt jucznych i mięsa armatniego dla Czarnego Stada!$B$BIch prawdziwym przywódcą jest nie kto inny jak Nefarian, potomek Śmiercioskrzydłego. Odkryłam też, gdzie w tej części cytadeli przebywają podwładni Nefariana.$B$BZanieś tę mapę marszałkowi Maxwellowi na Płonących Stepach. Zaznaczono na niej położenie tych nikczemników, żeby łatwo było ich rozpoznać.', 'Udaj się na Płonące Stepy i przekaż informacje Bijou marszałkowi Maxwellowi.', '', '', '', '', '', '', 0),
(5081, 'koKR', 'Misja Maxwella', 'Te informacje wypełniają luki w naszym skądinąd nienagannym rozpoznaniu Iglicy Czarnej Góry.$B$BAtak musi być decydujący, $N.$B$BNajpierw trzeba zniszczyć ich mistrza wojennego, trolla Wuna. Bez jego planów bitewnych orkowie Czarnej Skały pogrążą się w chaosie.$B$BNastępnie musisz wyeliminować nadzorcę ogrów, Omokka. Tchórzliwe ogry z Czarnej Skały są bezsilne bez jego przywództwa.$B$BNa koniec nadrządca cytadeli: Wyrmthalak. Gdy Wyrmthalak zginie, ich naczelne dowództwo straci ogniwo łączące je z wojskiem.', 'Udaj się do Iglicy Czarnej Góry i zabij Mistrza Wojennego Wuna, Nadzorcę Omokka i Nadrządcę Wyrmthalaka.', '', 'Wróć do marszałka Maxwella w Czuwaniu Morgana na Płonących Stepach.', '', '', '', '', 0),
(5089, 'koKR', 'Rozkaz generała Drakkisata', 'Przy zwłokach pokonanego gada znajdujesz coś, co wygląda na ważną notatkę: list od jego przełożonego, generała Drakkisata, dotyczący procedur.$B$BInstynkt podpowiada ci, że należy go zanieść marszałkowi Maxwellowi.', 'Zanieś rozkaz generała Drakkisata marszałkowi Maxwellowi na Płonących Stepach.', '', '', '', '', '', '', 0),
(5102, 'koKR', 'Kres generała Drakkisata', 'Walczymy z tymi bestiami na dwóch frontach: w naszej stolicy, Wichrogrodzie, zwalczamy je od środka, a tu, na Płonących Stepach, przenosimy walkę pod ich próg. Musimy zachować czujność, $N. Nikt nie może ujść naszemu gniewowi, tak jak nikt z naszych nie został oszczędzony, gdy uderzyli na nasze domy i rodziny.$B$BZnajdź tego generała Drakkisata i zniszcz go!$B$BTo z pewnością nie będzie proste zadanie, ale nagrody będą wystawne.', 'Udaj się do Iglicy Czarnej Góry i zabij generała Drakkisata.', '', 'Wróć do marszałka Maxwella w Czuwaniu Morgana na Płonących Stepach.', '', '', '', '', 0),
(5522, 'koKR', 'Leonid Barthalomew', 'Dostałam wiadomość od mojego pana, Vectusa. Właściwie ta wiadomość nie była od Vectusa... tylko od kogoś, kto nazywa się Leonid Barthalomew. Nie znam Leonida, ale on znał mojego pana, a nikt nie zna mojego pana, jeśli ten sobie tego nie życzy.$B$BLeonid pisze, że Vectus chce smoczych jaj. Chce, żebyś to ty mu je $gdostarczył:dostarczyła; do Kaplicy Świetlistej Nadziei na Wschodnich Plagowiskach.$B$BTo boli! Czemu ty? Czy Vectus mi nie ufa? A zresztą, nieważne... po prostu weź jaja i powiedz Leonidowi, że zrobiłam to, co rozkazał nasz pan.', 'Zanieś zamrożone jaja Leonidowi Barthalomewowi na Wschodnich Plagowiskach.', '', '', '', '', '', '', 0),
(7487, 'koKR', 'Dostrojenie do Jądra', 'Szczeliny budzą się, rozdzierają i zapadają wszędzie wokół nas, $N. Nie dalej niż dwa kroki od miejsca, w którym stoję, jest rozdarcie wiodące przez głębiny Czarnej Góry prosto w paszczę Władcy Ognia.$B$BZaskoczenie? Szkoda... Śmiertelne rasy nie potrafią pojąć tego, czego nie mogą zobaczyć, dotknąć ani poczuć.$B$BZapewniam cię, portal tam jest i można się do niego dostać.$B$BZaciekawiłem cię? Dostrojenie jest proste. Wypraw się do Otchłani Czarnej Góry i zdobądź fragment rdzenia. Przynieś mi go, a dostroję twoją esencję do portalu.', 'Wypraw się do portalu wejściowego Ognistej Czeluści w Otchłani Czarnej Góry i zdobądź fragment rdzenia. Gdy go zdobędziesz, wróć do Lothosa Budziciela Szczelin w Czarnej Górze.', '', 'Wróć do Lothosa Budziciela Szczelin w Czarnej Górze na Płonących Stepach.', '', '', '', '', 0),
(7563, 'koKR', 'Wściekłość krwi', 'Upiorne rumaki żyją w innym świecie, na ognistych Równinach Xoroth, a by spętać jedną z tych słynnych bestii, musisz przywołać potężne glify. Mogę wypisać je dla ciebie na pergaminie, ale najpierw będę potrzebował specjalnego atramentu.$B$BW odległym Zimozdroju żyje rasa sowostworów. Niegdyś były to czyste istoty, lecz demoniczne emanacje Wąwozu Mrocznego Szeptu doprowadziły je do obłędu i teraz w szale przemierzają śniegi.$B$BTo ich krwi potrzebuję do atramentu na twój pergamin. Przynieś mi ją.', 'Zanieś 30 butelek krwi rozwścieczonej bestii Mor\'zulowi Zwiastunowi Krwi na Płonących Stepach.', '', 'Wróć do Mor\'zula Zwiastuna Krwi przy Ołtarzu Burz na Płonących Stepach.', '', '', '', '', 0),
(7564, 'koKR', 'Dzikooki', 'Mój sługa, Gorzeeki, to całkiem wprawny alchemik. Może przygotować atrament potrzebny do twojego pergaminu. Zebrałem krew, którą $gzdobyłeś:zdobyłaś; – zanieś ją Gorzeekiemu, żeby mógł zacząć pracę.', 'Zanieś skrzynkę krwi Gorzeekiemu Dzikookiemu przy Ołtarzu Burz na Płonących Stepach.', '', '', '', '', '', '', 0),
(7626, 'koKR', 'Dzwon Dethmoory', 'Dzwon Dethmoory, nazwany na cześć nieżyjącej czarnoksiężniczki Dethmoory Mrokookiej, to jedno z trzech narzędzi potrzebnych do stworzenia Kręgu Większego Przywołania. Właściwie zestrojone z Kołem i Świecą, te przedmioty przewodzą ogromne zasoby mocy tajemnej.$B$BMój sługa Gorzeeki potrafi wykonać taki dzwon, ale będzie do tego potrzebował dużego zapasu eliksirów mocy cienia. Zdobądź eliksiry od alchemika i zanieś je Gorzeekiemu.', 'Zanieś 2 eliksiry mocy cienia Gorzeekiemu Dzikookiemu na Płonących Stepach.', '', 'Wróć do Gorzeekiego Dzikookiego przy Ołtarzu Burz na Płonących Stepach.', '', '', '', '', 0),
(7627, 'koKR', 'Koło Czarnego Marszu', 'Koło Czarnego Marszu zawiera i ukierunkowuje gwałtowne energie niezbędne dla Kręgu Większego Przywołania. Aby Gorzeeki mógł wykonać koło, będzie potrzebował zarówno dużych lśniących odłamków od zaklinacza, jak i rudy czarnorytu od mistrza górnictwa.$B$BZdobądź je i zanieś mojemu słudze.', 'Zanieś 6 dużych lśniących odłamków i 25 rud czarnorytu Gorzeekiemu na Płonących Stepach.', '', 'Wróć do Gorzeekiego Dzikookiego przy Ołtarzu Burz na Płonących Stepach.', '', '', '', '', 0),
(7628, 'koKR', 'Świeca zagłady', 'Świeca zagłady gromadzi ogień i kieruje go przeciwko tym, którzy chcieliby zakłócić twój rytuał. Jeśli podczas tworzenia Kręgu Większego Przywołania twoja świeca będzie zapalona, każdy niesforny demon zostanie spalony w jej płomieniach!$B$BUtrzymanie tego ognia w ryzach nie jest łatwe i wymaga esencji zawartej w łuskach czarnego smoka. Zdobądź te łuski od garbarza i zanieś je Gorzeekiemu Dzikookiemu.', 'Zanieś 3 czarne smocze łuski Gorzeekiemu Dzikookiemu na Płonących Stepach.', '', 'Wróć do Gorzeekiego Dzikookiego przy Ołtarzu Burz na Płonących Stepach.', '', '', '', '', 0),
(7629, 'koKR', 'Dostawa chochlika', 'Do pergaminu Mor\'zula potrzebny jest jeszcze jeden zabieg: papier nasycony ksorotiańskim gwiezdnym pyłem. I... obawiam się, że nie zrobię tego tutaj. Nie mam sprzętu!$B$BIstnieje jednak pracownia alchemiczna, w której jest wszystko, czego trzeba. Znajduje się w Scholomancjum, na wyspie Caer Darrow na Plagowiskach.$B$BJa nie mogę się tam wybrać, ale masz – weź ten słoik. Siedzi w nim chochlik, całkiem sprytny. Wypuść go w pracowni alchemicznej, a on nasyci pergamin.', 'Zanieś chochlika w słoiku do pracowni alchemicznej w Scholomancjum. Gdy pergamin zostanie wykonany, zwróć słoik Gorzeekiemu Dzikookiemu.', '', 'Wróć do Gorzeekiego Dzikookiego przy Ołtarzu Burz na Płonących Stepach.', 'Pergamin wykonany', '', '', '', 0),
(7630, 'koKR', 'Arkanit', 'Skoro Dzwon, Koło i Świeca są gotowe, powinienem zrobić czarny magnetyt. Podczas rytuału będziesz go potrzebować, by podtrzymać pozostałe przedmioty rytualne, gdyby zawiodły.$B$BDo wykonania magnetytu potrzebuję arkanitu. Masz trochę? Jeśli nie, to... będziesz $gmusiał:musiała; zdobyć arkanit od alchemika.$B$BWróć do mnie, gdy będziesz mieć arkanit, a wtedy zrobię czarny magnetyt.', 'Zanieś 1 sztabkę arkanitu Gorzeekiemu na Płonących Stepach.', '', 'Wróć do Gorzeekiego Dzikookiego przy Ołtarzu Burz na Płonących Stepach.', '', '', '', '', 0),
(7631, 'koKR', 'Upiorny rumak z Xoroth', 'Wszystkie przygotowania poczynione. Teraz musisz odprawić rytuał tworzenia Kręgu Większego Przywołania, a potem użyć pergaminu nasyconego ksorotiańskim gwiezdnym pyłem... by otworzyć portal do Xoroth.$B$BSpisałem instrukcje rytuału na zwoju. Przestudiuj je uważnie, bo jeśli chcesz odnieść sukces, musisz dokładnie wykonać każdy krok.$B$BPowodzenia, $N. I oby dusze twoich wrogów szybko trafiały do twojej sakwy na odłamki.', 'Przeczytaj instrukcje Mor\'zula. Przywołaj ksorotiańskiego upiornego rumaka, pokonaj go, a potem spętaj jego ducha ze sobą.', '', '', '', '', '', '', 0),
(7848, 'koKR', 'Dostrojenie do Jądra', 'Szczeliny budzą się, rozdzierają i zapadają wszędzie wokół nas, $N. Nie dalej niż dwa kroki od miejsca, w którym stoję, jest rozdarcie wiodące przez głębiny Czarnej Góry prosto w paszczę Władcy Ognia.$B$BZaskoczenie? Szkoda... Śmiertelne rasy nie potrafią pojąć tego, czego nie mogą zobaczyć, dotknąć ani poczuć.$B$BZapewniam cię, portal tam jest i można się do niego dostać.$B$BZaciekawiłem cię? Dostrojenie jest proste. Wypraw się do Otchłani Czarnej Góry i zdobądź fragment rdzenia. Przynieś mi go, a dostroję twoją esencję do portalu.', 'Wypraw się do portalu wejściowego Ognistej Czeluści w Otchłani Czarnej Góry i zdobądź fragment rdzenia. Gdy go zdobędziesz, wróć do Lothosa Budziciela Szczelin w Czarnej Górze.', '', 'Wróć do Lothosa Budziciela Szczelin w Czarnej Górze na Płonących Stepach.', '', '', '', '', 0),
(8636, 'koKR', 'Nestor Dudniąca Skała', '', '', '', '', '', '', '', '', 0),
(8683, 'koKR', 'Nestor Świtokrocz', '', '', '', '', '', '', '', '', 0),
(8961, 'koKR', 'Trzej królowie płomienia', 'Aby przywołać lorda Valthalaka, musimy najpierw zebrać pozostałe dwie trzecie amuletu. W tym celu potrzebujemy kosza żarowego i specjalnych węgli, które będą w nim płonąć.$B$BJest trzech władców ognia, którzy mają to, czego potrzebujemy: lord Incendius w Otchłani Czarnej Góry, Pirostrażnik Żarowidz w Iglicy Czarnej Góry i Książę Popiołów w Silithusie. Zdobądź od każdego z nich cząstkę ich szczątków, a potem wróć do mnie z uświęconym koszem żarowym, który możesz kupić od Argentowego Brzasku, jeśli jesteś przez nich $guhonorowany:uhonorowana;.', 'Zbierz incendycyt Incendiusa, żar Żarowidza i żużel Cyndersa, a także uświęcony kosz żarowy, i zanieś je Bodleyowi w Czarnej Górze.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8962, 'koKR', 'Ważne składniki', 'Słuchaj uważnie, $N. Skoro mamy już kosz żarowy i czym go rozpalić, wciąż potrzebujemy kolejnego składnika, którym go nasycimy; czegoś, co da ognisko skupienia dość silne, by zwabić ducha mojego zmarłego dawnego towarzysza.$B$BMor Szare Kopyto, nasz najwybitniejszy druid, miał wielu bliskich przyjaciół w Kręgu Cenariona, a niektórzy z nich padli ofiarą silithidów. Musisz zdobyć druidzkie szczątki od silithidów, które zamieszkują okolice Roju Regal w południowo-wschodnim Silithusie.', 'Zdobądź druidzkie szczątki i zanieś je Bodleyowi w Czarnej Górze.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8963, 'koKR', 'Ważne składniki', 'Słuchaj uważnie, $N. Skoro mamy już kosz żarowy i czym go rozpalić, wciąż potrzebujemy kolejnego składnika, którym go nasycimy; czegoś, co da ognisko skupienia dość silne, by zwabić ducha mojej zmarłej dawnej towarzyszki.$B$BIsalien, nasza kapłanka, dorastała w Zimozdroju, w Wiosce Gwiezdnej Bryzy. Musisz zdobyć relikwię z Wioski Gwiezdnej Bryzy od olbrzymów Mroźnych Maczug z Wąwozu Szeptu Mrozu w południowym Zimozdroju, znanych z tego, że od czasu do czasu napadają na północ.', 'Zdobądź relikwię z Wioski Gwiezdnej Bryzy i zanieś ją Bodleyowi w Czarnej Górze.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8964, 'koKR', 'Ważne składniki', 'Słuchaj uważnie, $N. Skoro mamy już kosz żarowy i czym go rozpalić, wciąż potrzebujemy kolejnego składnika, którym go nasycimy; czegoś, co da ognisko skupienia dość silne, by przywołać szczątki moich zmarłych dawnych towarzyszy.$B$BRodzeństwo, Jarien i Sothos, wyznawało drogę Szkarłatnej Krucjaty. Aspirowali do stanu rycerskiego w tej plugawej organizacji. Udaj się do Dłoni Tyra na Wschodnich Plagowiskach i zdobądź od tamtejszych pretorianów lśniący miecz żarliwości.', 'Zdobądź lśniący miecz żarliwości i zanieś go Bodleyowi w Czarnej Górze.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8965, 'koKR', 'Ważne składniki', 'Słuchaj uważnie, $N. Skoro mamy już kosz żarowy i czym go rozpalić, wciąż potrzebujemy kolejnego składnika, którym go nasycimy; czegoś, co da ognisko skupienia dość silne, by zwabić ducha mojego zmarłego dawnego towarzysza.$B$BOgrzy nekromanta, który z nami podróżował, Kormok, lubował się w przywoływaniu dusz wygnanych zmarłych z Wyspy Oczyszczenia u południowego wybrzeża Międzygórza. Udaj się tam i zdobądź z ich szczątków prochy duszy wygnańca.', 'Zdobądź prochy duszy wygnańca i zanieś je Bodleyowi w Czarnej Górze.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8966, 'koKR', 'Lewa część amuletu lorda Valthalaka', 'Mój przyjaciel, Mor Szare Kopyto, pierwszy padł ofiarą części amuletu lorda Valthalaka i zawartego w niej spaczającego fragmentu ducha. Po kradzieży księgi zaklęć i amuletu Valthalaka uciekaliśmy, ratując życie, z górnej części Iglicy Czarnej Góry. Po drodze Mor spadł do dolnej części iglicy.$B$BPóźniej dowiedzieliśmy się, że przeżył upadek, tylko po to, by zostać pojmanym i torturowanym przez Mistrza Wojennego Wuna. Kilku widmowych zabójców zakradło się tam i zabiło go na oczach Wuna.', 'Użyj kosza żarowego przywołania, by przywołać ducha Mora Szarego Kopyta, i zabij go. Wróć do Bodleya w Czarnej Górze z lewą częścią amuletu lorda Valthalaka i koszem żarowym przywołania.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8967, 'koKR', 'Lewa część amuletu lorda Valthalaka', 'Później, gdy sami robiliśmy, co w naszej mocy, by przetrwać, dowiedzieliśmy się, że Isalien, nocna elfka i kapłanka naszej kompanii, udała się do starożytnego miasta przodków nocnych elfów, znanego dziś jako Srogomłoty. Z tego, co zdołaliśmy ustalić, poszła tam zarówno z osobistych powodów, jak i po to, by odkryć tajemnice części amuletu, którą posiadała.$B$BNie udało jej się jednak. Doszły nas słuchy, że w Kaplicy Eldretharra wpadła w zasadzkę Alzzina Kształtującego Dzicz i jego sił.', 'Użyj kosza żarowego przywołania, by przywołać ducha Isalien, i zabij ją. Wróć do Bodleya w Czarnej Górze z lewą częścią amuletu lorda Valthalaka i koszem żarowym przywołania.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8968, 'koKR', 'Lewa część amuletu lorda Valthalaka', 'Rodzeństwo, Jarien i Sothos, postanowiło przyłączyć się do Szkarłatnej Krucjaty, gdy nasza kompania najemników się rozpadła. Zabrali ze sobą lewą część amuletu lorda Valthalaka. Krzyżyk na drogę, mówię, ale musimy odzyskać tę część.$B$BZ tego, co zdołaliśmy ustalić, zabił ich sam Wielki Krzyżowiec Dathrohan, gdy nie przeszli obrzędów inicjacji w jego komnacie w Szkarłatnym Bastionie.$B$BTak czy inaczej, my... to znaczy ty, wciąż musimy odzyskać tę część amuletu.', 'Użyj kosza żarowego przywołania, by przywołać Jarien i Sothosa, i zabij ich. Wróć do Bodleya w Czarnej Górze z lewą częścią amuletu lorda Valthalaka i koszem żarowym przywołania.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8969, 'koKR', 'Lewa część amuletu lorda Valthalaka', 'Mamy już, czego potrzeba, więc czas porozmawiać o tym, kogo będziesz przywoływać.$B$BKormok był w porządku jak na ogra, dopóki nie zwrócił się ku nekromancji. Od tamtej pory prawie całej naszej ekipie robiło się przy nim nieswojo. Nikogo więc nie zdziwiło, gdy zabrał swoją część amuletu i wrócił do nowego domu, Scholomancjum.$B$BAle nawet tam, a może zwłaszcza tam, nie był bezpieczny przed widmowymi zabójcami. Zabili go na oczach jego mistrza, Reza Szeptu Mrozu.', 'Użyj kosza żarowego przywołania, by przywołać ducha Kormoka, i zabij go. Wróć do Bodleya w Czarnej Górze z lewą częścią amuletu lorda Valthalaka i koszem żarowym przywołania.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8985, 'koKR', 'Więcej ważnych składników', 'Słuchaj uważnie, $N. Skoro znamy już położenie ostatniej części amuletu, wciąż potrzebujemy kolejnego składnika, którym nasycimy kosz żarowy; czegoś, co da ognisko skupienia dość silne, by zwabić ducha mojej zmarłej dawnej towarzyszki.$B$BIsalien, nasza kapłanka, dorastała w Zimozdroju, w Wiosce Gwiezdnej Bryzy. Musisz zdobyć relikwię z Wioski Gwiezdnej Bryzy od olbrzymów Mroźnych Maczug z Wąwozu Szeptu Mrozu w południowym Zimozdroju, znanych z tego, że od czasu do czasu napadają na północ.', 'Zdobądź relikwię z Wioski Gwiezdnej Bryzy i zanieś ją Bodleyowi w Czarnej Górze.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8986, 'koKR', 'Więcej ważnych składników', 'Słuchaj uważnie, $N. Skoro znamy już położenie ostatniej części amuletu, wciąż potrzebujemy kolejnego składnika, którym nasycimy kosz żarowy; czegoś, co da ognisko skupienia dość silne, by zwabić ducha mojego zmarłego dawnego towarzysza.$B$BMor Szare Kopyto, nasz najwybitniejszy druid, miał wielu bliskich przyjaciół w Kręgu Cenariona, a niektórzy z nich padli ofiarą silithidów. Musisz zdobyć druidzkie szczątki od silithidów, które zamieszkują okolice Roju Regal w południowo-wschodnim Silithusie.', 'Zdobądź druidzkie szczątki i zanieś je Bodleyowi w Czarnej Górze.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8987, 'koKR', 'Więcej ważnych składników', 'Słuchaj uważnie, $N. Skoro znamy już położenie ostatniej części amuletu, wciąż potrzebujemy kolejnego składnika, którym nasycimy kosz żarowy; czegoś, co da ognisko skupienia dość silne, by przywołać szczątki moich zmarłych dawnych towarzyszy.$B$BRodzeństwo, Jarien i Sothos, wyznawało drogę Szkarłatnej Krucjaty. Aspirowali do stanu rycerskiego w tej plugawej organizacji. Udaj się do Dłoni Tyra na Wschodnich Plagowiskach i zdobądź od tamtejszych pretorianów lśniący miecz żarliwości.$B', 'Zdobądź lśniący miecz żarliwości i zanieś go Bodleyowi w Czarnej Górze.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8988, 'koKR', 'Więcej ważnych składników', 'Słuchaj uważnie, $N. Skoro znamy już położenie ostatniej części amuletu, wciąż potrzebujemy kolejnego składnika, którym nasycimy kosz żarowy; czegoś, co da ognisko skupienia dość silne, by zwabić ducha mojego zmarłego dawnego towarzysza.$B$BOgrzy nekromanta, który z nami podróżował, Kormok, lubował się w przywoływaniu dusz wygnanych zmarłych z Wyspy Oczyszczenia u południowego wybrzeża Międzygórza. Udaj się tam i zdobądź z ich szczątków prochy duszy wygnańca.', 'Zdobądź prochy duszy wygnańca i zanieś je Bodleyowi w Czarnej Górze.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8989, 'koKR', 'Prawa część amuletu lorda Valthalaka', 'Mój przyjaciel, Mor Szare Kopyto, pierwszy padł ofiarą części amuletu lorda Valthalaka i zawartego w niej spaczającego fragmentu ducha. Po kradzieży księgi zaklęć i amuletu Valthalaka uciekaliśmy, ratując życie, z górnej części Iglicy Czarnej Góry. Po drodze Mor spadł do dolnej części iglicy.$B$BPóźniej dowiedzieliśmy się, że przeżył upadek, tylko po to, by zostać pojmanym i torturowanym przez Mistrza Wojennego Wuna. Kilku widmowych zabójców zakradło się tam i zabiło go na oczach Wuna.', 'Użyj kosza żarowego przywołania, by przywołać ducha Mora Szarego Kopyta, i zabij go. Wróć do Bodleya w Czarnej Górze z połączonym amuletem lorda Valthalaka i koszem żarowym przywołania.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8990, 'koKR', 'Prawa część amuletu lorda Valthalaka', 'Później, gdy sami robiliśmy, co w naszej mocy, by przetrwać, dowiedzieliśmy się, że Isalien, nocna elfka i kapłanka naszej kompanii, udała się do starożytnego miasta przodków nocnych elfów, znanego dziś jako Srogomłoty. Z tego, co zdołaliśmy ustalić, poszła tam zarówno z osobistych powodów, jak i po to, by odkryć tajemnice części amuletu, którą posiadała.$B$BNie udało jej się jednak. Doszły nas słuchy, że w Kaplicy Eldretharra wpadła w zasadzkę Alzzina Kształtującego Dzicz i jego sił.', 'Użyj kosza żarowego przywołania, by przywołać ducha Isalien, i zabij ją. Wróć do Bodleya w Czarnej Górze z połączonym amuletem lorda Valthalaka i koszem żarowym przywołania.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8991, 'koKR', 'Prawa część amuletu lorda Valthalaka', 'Rodzeństwo, Jarien i Sothos, postanowiło przyłączyć się do Szkarłatnej Krucjaty, gdy nasza kompania najemników się rozpadła. Zabrali ze sobą prawą część amuletu lorda Valthalaka. Krzyżyk na drogę, mówię, ale musimy odzyskać tę część.$B$BZ tego, co zdołaliśmy ustalić, zabił ich sam Wielki Krzyżowiec Dathrohan, gdy nie przeszli obrzędów inicjacji w jego komnacie w Szkarłatnym Bastionie.$B$BTak czy inaczej, my... to znaczy ty, wciąż musimy odzyskać tę część amuletu.', 'Użyj kosza żarowego przywołania, by przywołać Jarien i Sothosa, i zabij ich. Wróć do Bodleya w Czarnej Górze z połączonym amuletem lorda Valthalaka i koszem żarowym przywołania.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8992, 'koKR', 'Prawa część amuletu lorda Valthalaka', 'Mamy już, czego potrzeba, więc czas porozmawiać o tym, kogo przywołasz jako następnego.$B$BKormok był w porządku jak na ogra, dopóki nie zwrócił się ku nekromancji. Od tamtej pory prawie całej naszej ekipie robiło się przy nim nieswojo. Nikogo więc nie zdziwiło, gdy zabrał swoją część amuletu i wrócił do nowego domu, Scholomancjum.$B$BAle nawet tam, a może zwłaszcza tam, nie był bezpieczny przed widmowymi zabójcami. Zabili go na oczach jego mistrza, Reza Szeptu Mrozu.', 'Użyj kosza żarowego przywołania, by przywołać ducha Kormoka, i zabij go. Wróć do Bodleya w Czarnej Górze z połączonym amuletem lorda Valthalaka i koszem żarowym przywołania.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8994, 'koKR', 'Ostatnie przygotowania', 'Jesteśmy prawie u celu, $N. Pozostało tylko zdobyć jeszcze kilka składników, żebym mógł zestroić kosz żarowy i sprawić, by przywołał lorda Valthalaka.$B$BNa początek muszę cię prosić, byś $gwyruszył:wyruszyła; do Iglicy Czarnej Góry i zabijał tamtejszych orków. Noszą karwasze zawierające śladowe ilości metali, których potrzebuję, więc będę potrzebował ich całkiem sporo, żeby wydobyć odpowiednią ilość. Następnie, by dokończyć nasycanie, musisz mi przynieść flaszkę najwyższej mocy.$B$BPowodzenia, $N!', 'Zbierz 40 karwaszy Czarnej Skały i zdobądź flaszkę najwyższej mocy. Zanieś je Bodleyowi w Czarnej Górze.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(8995, 'koKR', 'Mea culpa, lordzie Valthalaku', 'Wszystko gotowe, $N.$B$BZa życia lord Valthalak zamieszkiwał komnatę, w której teraz przebywa Bestia. Udaj się tam i użyj kosza żarowego przywołania, by przywołać lorda Valthalaka. Kosz przywróci mu ciało, więc trzeba będzie go zabić jeszcze raz. Ja najpierw zająłbym się Bestią i koniecznie zabrałbym ze sobą dość przyjaciół, by przetrwać w górnej części Iglicy Czarnej Góry.$B$BGdy już pozbędziesz się Valthalaka, użyj amuletu na jego zwłokach. Gdy jego duch znów będzie całością, zapewne zechce też odzyskać swój amulet.$B$BPowodzenia!', 'Użyj kosza żarowego przywołania, by przywołać lorda Valthalaka. Pozbądź się go i użyj amuletu lorda Valthalaka na jego zwłokach. Następnie oddaj amulet lorda Valthalaka duchowi lorda Valthalaka.', '', 'Wróć do ducha lorda Valthalaka w Iglicy Czarnej Góry.', '', '', '', '', 0),
(8996, 'koKR', 'Powrót do Bodleya', 'Tym razem puszczę twoje zuchwalstwo płazem, $N, bo $gdokonałeś:dokonałaś; dziś szlachetnego czynu: $gzwróciłeś:zwróciłaś; mi resztę mojego skradzionego ducha. Mimo oczywistej słabości swojej natury $gokazałeś:okazałaś; odwagę, której nie mieli, i zapewne nigdy nie mieliby, ci, którzy mnie okradli!$B$BWróć do nich, zanim zmienię zdanie i zabiję cię na miejscu. Wróć i powiedz im, że są bezpieczni... na razie.', 'Wróć do Bodleya w Czarnej Górze i oddaj mu kosz żarowy przywołania.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(3801, 'koKR', 'Czy przywiodła cię tu chciwość, czy bezinteresowne oddanie – to, czego się podejmujesz, posłuży nam wszystkim.', 0),
(3802, 'koKR', 'Młot pewnie wsuwa się na miejsce, w uścisk potężnego pomnika Czarnorytych. U podstawy posągu otwiera się maleńka skrytka. W środku znajdujesz...', 0),
(3823, 'koKR', 'Znakomicie, żołnierzu! Orkowie i ogry będą się otrząsać po tym ciosie całe minuty, może nawet godziny!', 0),
(3824, 'koKR', 'Tylko spójrz na to, żołnierzu. Obrzydlistwo! Kiedy ocalałe ogry z Ognistych Trzewi zobaczą tę tłustą gębę nabitą na pal na szczycie swojej góry, wybuchnie zbiorowa histeria!$B$B<Oralius zanosi się dzikim rechotem.>', 0),
(3825, 'koKR', 'Znakomita robota, żołnierzu! Po prostu zdumiewająca! Och, dostanę za to medal za odwagę, eee, to znaczy, zostaniesz za to sowicie $gnagrodzony:nagrodzona;!', 0),
(4022, 'koKR', '<Cyrus ogląda wylinkę.>$B$B$GDowiodłeś:Dowiodłaś;, że nie jesteś całkiem $gbezużyteczny:bezużyteczna;, $gśmiertelniku:śmiertelniczko;.', 0),
(4023, 'koKR', '<Cyrus ogląda wylinkę.>$B$B$GDowiodłeś:Dowiodłaś;, że nie jesteś całkiem $gbezużyteczny:bezużyteczna;, $gśmiertelniku:śmiertelniczko;.', 0),
(4024, 'koKR', '<Cyrus wyrywa ci z rąk ognistą esencję.>$B$BTAK!$B$BBierz swoją nagrodę i precz. Zejdź mi natychmiast z oczu!', 0),
(4123, 'koKR', 'Masz Serce! Niesamowite! Jest jeszcze piękniejsze, niż sobie wyobrażałem!$B$BProszę, $N, weź to jako zapłatę!', 0),
(4136, 'koKR', 'Aha! $GZnalazłeś:Znalazłaś; go! I... wygląda na to, że mój braciszek nie chciał pójść po dobroci. Szkoda. Chętnie zobaczyłabym jego minę, gdy mówię mu o naszym planie wydania go Revilgazowi.$b$bDziękuję, $N. Moja rodzina jest bardzo szczęśliwa. A Ribbly jeszcze nigdy nie wyglądał tak spokojnie jak teraz.', 0),
(4182, 'koKR', 'Doskonała rzeź, $N. Skoro już wiemy, że radzisz sobie ze smoczym pomiotem, możemy porozmawiać o pilniejszych sprawach.', 0),
(4183, 'koKR', '<Sędzia Solomon otwiera zapieczętowany list od Helendisa i zaczyna czytać.>', 0),
(4184, 'koKR', 'Smoki? Niemożliwe!', 0),
(4185, 'koKR', '<Bolvar ujmuje się pod brodę, jakby pogrążony w myślach.>$B$BChoć szanuję stanowisko lady Prestor, uważam, że jest wyjście z tego dylematu, które może rozwiać wszystkie nasze obawy.', 0),
(4186, 'koKR', 'Mogło być gorzej, jak sądzę...$B$B<Sędzia Solomon mierzy cię wzrokiem.>$B$BWygląda na to, że los Jeziernych Włości spoczywa wyłącznie na twoich barkach.$B$B<Zauważasz, że sędzia Solomon szybko mruga. Wygląda na to, że płacze.>', 0),
(4223, 'koKR', '<Marszałek Maxwell się śmieje.>', 0),
(4224, 'koKR', 'Mogłem cię ostrzec, ale co by to była za zabawa?', 0),
(4262, 'koKR', 'Incendius? O rety...', 0),
(4263, 'koKR', 'O rety! Na pewno Incendius powiedział „Ragnaros”?$b$b<Jalinda wręcza ci coś i klepie cię po nadgarstku, pogrążając się w myślach.>', 0),
(4283, 'koKR', 'Udało ci się! Twoja nagroda to: POMASUJ MI BRZUSZEK! NO DALEJ! POMASUJ!', 0),
(4286, 'koKR', '<Oralius zaczyna grzebać w górze nerek.>$B$BOCH, CUDOWNIE!$B$B<Oralius wtyka swój wielki nos w stertę i wciąga powietrze.>$B$BPYSZNE! Popatrz tylko na te wszystkie smakołyki!$B$BWeź jedną dla siebie, $N. Starczy dla wszystkich.', 0),
(4296, 'koKR', 'Ach, $gznalazłeś:znalazłaś; tablicę! A twój odpis jest znakomity! Na pewno nie jesteś skrybą?$B$BProszę, $N. Oto obiecana zapłata.', 0),
(4463, 'koKR', 'Bierz swoją błyskotkę, $ggłupcze:głupia;. Zostaw mnie z moimi studiami!', 0),
(4481, 'koKR', 'To hańba dla jego pamięci... śmiertelnik taki jak ty kończy dzieło jego życia.$B$BBierz swój amalgamat i precz!', 0),
(4482, 'koKR', 'Ukończenie libramu, który trzymasz, zajęło Karielowi tyle, ile trwałoby kilka twoich żywotów. I po co? Żeby jego uczeń mógł stać na Płonących Stepach i kalać jego badania, by zaspokoić nigdy niekończący się głód magii... Przeklęty niech będzie ten plugawy nałóg.$B$BBrzydzę się twoim brakiem współczucia i nienasyconą chciwością. Precz!', 0),
(4483, 'koKR', 'Inne libramy przepadły na tym świecie. Przepadły w miejscach, do których nie $godważyłbyś:odważyłabyś; się wejść. W miejscach, o których $gmodliłbyś:modliłabyś; się, by nie istniały.$B$BWchłonę energie tych składników. Tobie przypadną pozostałe odpady...', 0),
(4484, 'koKR', 'Głowa mi pęka... Energie bezmiernych przestworzy, z których składa się nasz wszechświat... ARGH!$B$BBierz, czego chcesz, i odejdź!', 0),
(4701, 'koKR', 'Nie rozpamiętuj jej cierpienia, $N. Ta bestia była spaczona – była dziełem mrocznej magii. $GOddałeś:Oddałaś; Przymierzu wielką przysługę i zostaniesz $gnagrodzony:nagrodzona;.', 0),
(4726, 'koKR', 'Zadziałało! Masz esencję! Dobra robota, $N! Dobra robota!$B$BTa esencja będzie nieoceniona w moich badaniach. Mam nadzieję, że pewnego dnia nauczę się chwytać żywe smocze pisklęta, a może i ich jaja. Gdybym znalazła na to sposób, zazdrościliby mi badacze smoków z całego świata!$B$BMój pracodawca też byłby zadowolony, a jak już mówiłam, to ktoś, kogo lepiej zadowalać...', 0),
(4729, 'koKR', 'W samą porę je $gzłapałeś:złapałaś;, $N. Trochę później i nie dałoby się ich wyszkolić! Daj mi minutkę, a przygotuję malucha, żebyś $gmógł:mogła; go zabrać do domu.', 0),
(4734, 'koKR', 'Zadziałało? Wspaniale! Wiedziałam, że zadziała!$b$bGdy cię nie było, pracowałam nad nową wersją jajoscyloskopu. Ta ma o wiele większy zasięg.$b$bMasz, weź jeden, na wypadek gdybyś $gwracał:wracała; do Iglicy Czarnej Góry.', 0),
(4735, 'koKR', 'Łał, masz je! Moduł kolektroniczny zadziałał! Jestem geniuszem!$B$BDziękuję, $N. Mój mecenas będzie bardzo zadowolony z tych jaj...', 0),
(4764, 'koKR', '$GZnalazłeś:Znalazłaś; ją! A więc plotki były prawdziwe!$B$BDziękuję, $N. Mój mecenas, hrabia Remington Ridgewell, bardzo się ucieszy z tego nabytku do swojej kolekcji.', 0),
(4808, 'koKR', 'To nie jest koc! Ale co my tu mamy? List od Tinkee? Ciekawe, co ma do powiedzenia...$b$bAch, prowadzi badania na Płonących Stepach. To ma sens – tam nie brakuje smoczego pomiotu. Och, ale spójrz! Pisze tu, że potrzebuje części do urządzenia, które chce zbudować. Chyba tu wkraczam ja, co?', 0),
(4810, 'koKR', '$GPrzyniosłeś:Przyniosłaś; je! Wspaniale! Zaraz biorę się do pracy! Wielkie dzięki, $N!$b$bTak bardzo mi $gpomogłeś:pomogłaś;, że być może później będę cię potrzebować do jeszcze ważniejszych zadań...', 0),
(4862, 'koKR', 'Ale ładunek! No, spójrz tylko na te wszystkie jaja! Powinny przynieść niezłą sumkę złota.$B$BZgodnie z obietnicą, oto twój własny mały stworek. Uważaj, żeby cię nie ugryzł!', 0),
(4866, 'koKR', 'Z tego wyjdzie najlepsze piwo w historii!$B$BCo, $gmyślałeś:myślałaś;, że do czego tego użyję? Do trucia czy co??$B$BZwariowana dzieciarnia...', 0),
(4907, 'koKR', 'Felnok miał rację! Znów potrzebuję twojej pomocy, a tym razem... będzie naprawdę niebezpiecznie.$b$bJesteś $ggotów:gotowa;??', 0),
(5002, 'koKR', 'To pokrywa się z wieloma rzeczami, które już wiedzieliśmy. Mimo to są to interesujące i dość niepomyślne informacje.$B$BOznaczenia na tej mapie okażą się cenne w przerzedzaniu szeregów Czarnej Skały.', 0),
(5081, 'koKR', 'Doskonała robota, $N. W najgorszym razie $gkupiłeś:kupiłaś; nam trochę czasu – cennego, bardzo cennego czasu.', 0),
(5089, 'koKR', 'Sprawa się komplikuje...', 0),
(5102, 'koKR', 'Z pewnością następnym celem naszego uderzenia będą ich smoczy władcy. Dobra robota, $gdzielny żołnierzu:dzielna żołnierko; Przymierza! Doprawdy dobra robota.', 0),
(5522, 'koKR', 'Ach, bardzo dobrze. Nie wiesz, dla jakiej złej mocy $gpracowałeś:pracowałaś;, ale teraz poznasz prawdę. I nie lękaj się – nie jestem sługą tego pana. Jestem Leonid Barthalomew, zwany przez braci z Argentowego Brzasku „Czcigodnym”.$b$bPodstępem skłoniłem Tinkee, by przysłała do mnie ciebie i smocze jaja. I dobrze, że mój podstęp się powiódł, bo gdyby te jaja trafiły tam, dokąd miały trafić, wielka moc wpadłaby w ręce wroga.', 0),
(7487, 'koKR', 'Mogę teraz przenieść cię do Ognistej Czeluści. Wystarczy poprosić.', 0),
(7563, 'koKR', 'Ach, bardzo dobrze. Każę przedestylować tę krew na atrament i użyję go do obiecanego pergaminu. A może zostawię odrobinę dla siebie, bo podobno jej smak przyprawia o euforię...', 0),
(7564, 'koKR', 'Och, to krew. W takim razie musi być od mistrza Mor\'zula. On tak ją uwielbia i uwielbia patrzeć, jak się leje. Ja jednak wolę, gdy krąży w żyłach małego gryzonia. Tak dłużej zostaje ciepła... aż się jej zachce.$B$BTo potężna krew. Mor\'zul pewnie robi kolejny pergamin do przywołania upiornego rumaka! Jak ekscytująco!$B$BJeśli to prawda i to ty masz odprawić rytuał, to... będziesz potrzebować znacznie więcej niż krwi, $gprzyjacielu:przyjaciółko;.', 0),
(7626, 'koKR', 'Bardzo dobrze! Mam nadzieję, że zdobycie tych eliksirów nie było zbyt trudne. Alchemicy bywają tacy skąpi, jeśli chodzi o ich wyroby...$B$BZrobię dzwon i zatrzymam go, dopóki nie będziesz $ggotów:gotowa; do rytuału.', 0),
(7627, 'koKR', 'Są! Słyszałem, że rudę czarnorytu można znaleźć tylko w głębinach Czarnej Góry, a te odłamki też pewnie nie były łatwe do zdobycia. Często zdumiewa mnie oddanie was, czarnoksiężników. Gdybyście całą tę energię skierowali na sztukę łapania robaków, och... cóż to byłaby za uczta!$B$BWybacz, drobna dygresja. Zrobię koło i przechowam je dla ciebie, dopóki nie będziesz $ggotów:gotowa; do rytuału.', 0),
(7628, 'koKR', 'Ach, bardzo dobrze. Będą mi potrzebne, by utrzymać w ryzach ogień świecy. Teraz, gdy mam łuski, zrobię świecę i przechowam ją, dopóki nie będziesz $ggotów:gotowa; do rozpoczęcia rytuału Kręgu Większego Przywołania.', 0),
(7629, 'koKR', 'Ach, dobrze. J\'eevee wykonał pergamin. Jak tam w Scholomancjum? Uroczo, prawda? A tamtejsze robaki... podobno są przepyszne!$B$BDobra robota, $N, i dziękuję za zwrot słoika. Mam go od dawna... i nie jest na sprzedaż!', 0),
(7630, 'koKR', 'Masz go! Świetna robota! Teraz mogę wykonać magnetyt. Kiedy w końcu będziesz $ggotów:gotowa; do rytuału tworzenia Kręgu Większego Przywołania, przyda ci się magnetyt, żeby rytuał nie spalił na panewce!', 0),
(7631, 'koKR', 'Duch ksorotiańskiego upiornego rumaka został pokonany. Choć wściekłość wciąż pulsuje w jego widmowych bokach, wiesz, że dusza bestii należy do ciebie...$B$BSzepcze ci do umysłu mroczną magię i zaszczepia w tobie wiedzę o tym, jak przywołać upiornego rumaka.', 0),
(7848, 'koKR', 'Mogę teraz przenieść cię do Ognistej Czeluści. Wystarczy poprosić.', 0),
(8636, 'koKR', 'To, co żywe, musi umrzeć i wrócić do ziemi, lecz to, co duchowe, trwa wiecznie. Życzę ci wszystkiego dobrego, $N, i ofiarowuję ten dar...', 0),
(8961, 'koKR', 'Robisz na mnie wrażenie, $N, ale nie ma czasu do stracenia. Dam ci kolejne zadanie, bo zanim ruszymy dalej, musisz zdobyć jeszcze kilka ważnych składników.$B$BPorozmawiaj ze mną znowu, gdy poczujesz, że jesteś $ggotów:gotowa; na czekające cię wyzwanie.', 0),
(8962, 'koKR', 'Dobrze wykonane zadanie, $N. Nasycę kosz żarowy esencją szczątków.$B$BTeraz pozostaje tylko udać się do dolnej części Iglicy Czarnej Góry, do komnaty w Tazz\'Alaor, gdzie przebywa Mistrz Wojenny Wun, i użyć kosza, by przywołać spaczonego ducha mojego dawnego kompana, Mora Szarego Kopyta. Nie zazna spokoju, dopóki nie odbierze mu się części amuletu.', 0),
(8963, 'koKR', 'Dobrze wykonane zadanie, $N. Nasycę kosz żarowy esencją relikwii.$B$BTeraz pozostaje tylko udać się do Kaplicy Eldretharra we wschodnim skrzydle Srogomłotów i użyć kosza, by przywołać ducha mojej dawnej towarzyszki, Isalien. Jej duch został spaczony przez część amuletu Valthalaka, którą posiadała, i zawartą w niej cząstkę jego duszy.', 0),
(8964, 'koKR', 'Dobrze wykonane zadanie, $N. Nasycę kosz żarowy esencją miecza.$B$BTeraz pozostaje tylko dostać się do Karmazynowego Tronu w Szkarłatnym Bastionie w Stratholmie i użyć kosza, by przywołać szczątki moich dawnych kompanów, Jarien i Sothosa. Ich dusze zostały jeszcze bardziej wypaczone przez część amuletu Valthalaka, którą posiadali, i zawarty w niej jego duch.', 0),
(8965, 'koKR', 'Dobrze wykonane zadanie, $N. Nasycę kosz żarowy esencją prochów.$B$BTeraz pozostaje tylko dostać się do Scholomancjum, do komnaty Reza Szeptu Mrozu, i użyć kosza, by przywołać ducha mojego dawnego kompana, Kormoka. Część amuletu i zawarty w niej duch Valthalaka spaczyły go jeszcze bardziej i nie zazna spokoju, dopóki siłą mu jej nie odbierzesz.', 0),
(8966, 'koKR', '$GDokonałeś:Dokonałaś; wielkiej rzeczy, $N. Jeden duch spoczywa w pokoju, ale czeka nas jeszcze wiele pracy, zanim będziemy mogli zostawić to wszystko za sobą.$B$BNiestety, nie wiem, gdzie spoczywa ten, kto zginął z prawą częścią amuletu. Ale nie obawiaj się: za życia parałem się sztuką wróżbiarstwa, więc mam dla ciebie kolejne zadanie, które pozwoli nam wytropić ostatnią część.', 0),
(8967, 'koKR', 'Dziękuję, $N, że $gpozwoliłeś:pozwoliłaś; spocząć duchowi Isalien. Teraz może odnajdzie spokój u swojej bogini. Ale czeka nas jeszcze mnóstwo pracy, jeśli mamy się wyplątać z tej pięknej kabały, w którą wpadliśmy.$B$BNiestety, nie wiem, gdzie spoczywa ten, kto zginął z prawą częścią amuletu. Ale nie obawiaj się: za życia parałem się sztuką wróżbiarstwa, więc mam dla ciebie kolejne zadanie, które pozwoli nam wytropić ostatnią część.', 0),
(8968, 'koKR', 'Chyba dobrze, że dusze tych dwojga w końcu spoczęły w pokoju, nawet jeśli za życia ich nie lubiłem. Tak czy inaczej, mamy to, czego szukaliśmy, a to zdecydowanie dobra rzecz!$B$BNiestety, nie wiem, gdzie spoczywa ten, kto zginął z prawą częścią amuletu. Ale nie obawiaj się: za życia parałem się sztuką wróżbiarstwa, więc mam dla ciebie kolejne zadanie, które pozwoli nam wytropić ostatnią część.', 0),
(8969, 'koKR', 'Dobra robota, $N! Kormok nie był taki zły jak na ogra, przynajmniej póki żył, więc mam nadzieję, że zazna odpoczynku, na jaki zasługuje. Ale czeka nas jeszcze praca.$B$BNiestety, nie wiem, gdzie spoczywa ten, kto zginął z prawą częścią amuletu. Ale nie obawiaj się: za życia parałem się sztuką wróżbiarstwa, więc mam dla ciebie kolejne zadanie, które pozwoli nam wytropić ostatnią część.', 0),
(8985, 'koKR', 'Dobrze wykonane zadanie, $N. Nasycę kosz żarowy esencją relikwii.$B$BTeraz pozostaje tylko udać się do Kaplicy Eldretharra we wschodnim skrzydle Srogomłotów i użyć kosza, by przywołać ducha mojej dawnej towarzyszki, Isalien. Jej duch został spaczony przez część amuletu Valthalaka, którą posiadała, i zawartą w niej cząstkę jego duszy.$B$BA, przy okazji, zostało mi trochę krwawego wodorostu z twojej wyprawy na Wyspę Alcaz, więc zrobiłem z niego dla ciebie kilka mikstur. Wybierz sobie!', 0),
(8986, 'koKR', 'Dobrze wykonane zadanie, $N. Nasycę kosz żarowy esencją szczątków.$B$BTeraz pozostaje tylko udać się do dolnej części Iglicy Czarnej Góry, do komnaty w Tazz\'Alaor, gdzie przebywa Mistrz Wojenny Wun, i użyć kosza, by przywołać spaczonego ducha mojego dawnego kompana, Mora Szarego Kopyta. Nie zazna spokoju, dopóki nie odbierze mu się części amuletu.$B$BA, przy okazji, zostało mi trochę krwawego wodorostu z twojej wyprawy na Wyspę Alcaz, więc zrobiłem z niego dla ciebie kilka mikstur. Wybierz sobie!', 0),
(8987, 'koKR', 'Dobrze wykonane zadanie, $N. Nasycę kosz żarowy esencją miecza.$B$BTeraz pozostaje tylko dostać się do Karmazynowego Tronu w Szkarłatnym Bastionie w Stratholmie i użyć kosza, by przywołać szczątki moich dawnych kompanów, Jarien i Sothosa. Ich dusze zostały jeszcze bardziej wypaczone przez część amuletu Valthalaka, którą posiadali, i zawarty w niej jego duch.$B$BA, przy okazji, zostało mi trochę krwawego wodorostu z twojej wyprawy na Wyspę Alcaz, więc zrobiłem z niego dla ciebie kilka mikstur. Wybierz sobie!', 0),
(8988, 'koKR', 'Dobrze wykonane zadanie, $N. Nasycę kosz żarowy esencją prochów.$B$BTeraz pozostaje tylko dostać się do Scholomancjum, do komnaty Reza Szeptu Mrozu, i użyć kosza, by przywołać ducha mojego dawnego kompana, Kormoka. Część amuletu i zawarty w niej duch Valthalaka spaczyły go jeszcze bardziej i nie zazna spokoju, dopóki siłą mu jej nie odbierzesz.$B$BA, przy okazji, zostało mi trochę krwawego wodorostu z twojej wyprawy na Wyspę Alcaz, więc zrobiłem z niego dla ciebie kilka mikstur. Wybierz sobie!', 0),
(8989, 'koKR', 'Dziękuję, że $gpomogłeś:pomogłaś; Morowi Szaremu Kopytu, $N. Kolejny duch spoczywa w pokoju, a my mamy znów scalony amulet! Ale wciąż czeka nas najtrudniejsza próba.$B$BAby kosz żarowy został zestrojony do przywołania lorda Valthalaka, trzeba zebrać jeszcze kilka przedmiotów i przynieść je tu do mnie.', 0),
(8990, 'koKR', 'Dziękuję, $N, że $gpozwoliłeś:pozwoliłaś; spocząć duchowi Isalien. Teraz może odnajdzie spokój u swojej bogini. I mamy też znów scalony amulet! Ale wciąż czeka nas najtrudniejsza próba.$B$BAby kosz żarowy został zestrojony do przywołania lorda Valthalaka, trzeba zebrać jeszcze kilka przedmiotów i przynieść je tu do mnie.', 0),
(8991, 'koKR', 'Chyba dobrze, że dusze tych dwojga w końcu spoczęły w pokoju, nawet jeśli za życia ich nie lubiłem. Tak czy inaczej, mamy to, czego szukaliśmy, a amulet jest znów scalony! Ale wciąż czeka nas najtrudniejsza próba.$B$BAby kosz żarowy został zestrojony do przywołania lorda Valthalaka, trzeba zebrać jeszcze kilka przedmiotów i przynieść je tu do mnie.', 0),
(8992, 'koKR', 'Dobra robota, $N! Kormok nie był taki zły jak na ogra, przynajmniej póki żył, więc mam nadzieję, że zazna odpoczynku, na jaki zasługuje. A teraz mamy cały amulet! Ale wciąż czeka nas najtrudniejsza próba.$B$BAby kosz żarowy został zestrojony do przywołania lorda Valthalaka, trzeba zebrać jeszcze kilka przedmiotów i przynieść je tu do mnie.', 0),
(8994, 'koKR', 'To już wszystko. Wydobędę metal z karwaszy i nasycę kosz żarowy tymi ostatnimi składnikami. Wtedy będzie gotowy, żebyś $gprzywołał:przywołała; lorda Valthalaka i w końcu $gzwrócił:zwróciła; mu jego amulet ducha.$B$B$GPrzebyłeś:Przebyłaś; długą drogę, $N, nie zawahaj się teraz, gdy koniec jest w zasięgu wzroku!', 0),
(8995, 'koKR', 'Masz szczęście, że wiem, iż nie należysz do grupy, która mi to ukradła.$B$BTeraz odbiorę to, co moje, $gśmiertelniku:śmiertelniczko;! Daj mi amulet!', 0),
(8996, 'koKR', 'Naprawdę tak powiedział? Łał, nie mogę uwierzyć, że odwoła widmowych zabójców i tropicieli, nawet jeśli dał do zrozumienia, że w przyszłości może jeszcze skrzywdzić moich żyjących towarzyszy.$B$BTo wielki dzień, $N! $GDokonałeś:Dokonałaś; tego, co udaje się niewielu, i $gzdjąłeś:zdjęłaś; z nas, przynajmniej częściowo, niektóre z naszych dawnych win.$B$BDziękuję! W dowód wdzięczności chcę ci dać to. Możesz tego użyć, by przywoływać duchy w tych samych nawiedzonych miejscach co dotąd, a także w kilku innych.', 0),
(11739, 'koKR', 'Zbezcześć wielkie ognisko Przymierza na Płonących Stepach!', 0),
(11768, 'koKR', 'Zbezcześć wielkie ognisko Hordy na Płonących Stepach!', 0),
(11810, 'koKR', 'Uczcij płomień Płonących Stepów!', 0),
(11844, 'koKR', 'Uczcij płomień Płonących Stepów!', 0),
(13026, 'koKR', 'To, co żywe, musi umrzeć i wrócić do ziemi, lecz to, co duchowe, trwa wiecznie. Życzę ci wszystkiego dobrego, $N, i ofiarowuję ten dar...', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(3802, 'koKR', 'Posąg groźnie góruje nad tobą.', 0),
(3823, 'koKR', 'Na twoim mundurze nie ma nawet w połowie dość krwi, żołnierzu!', 0),
(3824, 'koKR', 'Och, cóż za wspaniały dzień! $GWróciłeś:Wróciłaś; z głową?', 0),
(3825, 'koKR', 'No i? $GNamalowałeś:Namalowałaś; jakieś obrazki z tego wydarzenia?', 0),
(4022, 'koKR', '<Oczy Cyrusa zmieniają się w dwie płonące kule.>', 0),
(4023, 'koKR', '<Oczy Cyrusa zmieniają się w dwie płonące kule.>', 0),
(4024, 'koKR', 'Czy olbrzym padł?', 0),
(4123, 'koKR', 'Masz Serce góry? Dla mnie jego wartość jest bezcenna.', 0),
(4136, 'koKR', 'Masz Ribbly\'ego? A przynajmniej jakąś jego część?', 0),
(4182, 'koKR', 'Jak idą łowy na smoki?', 0),
(4183, 'koKR', 'Witaj, $N. Czy myśmy się już kiedyś spotkali? Wyglądasz znajomo.', 0),
(4184, 'koKR', 'Co cię sprowadza do Twierdzy Wichrogród?', 0),
(4185, 'koKR', '<Bolvar bacznie ci się przygląda.>', 0),
(4186, 'koKR', 'Jakieś wieści od Bolvara?', 0),
(4224, 'koKR', '$GRozmawiałeś:Rozmawiałaś; już z Johnem?', 0),
(4262, 'koKR', '<Wygląda na to, że Jalinda wpatruje się w twoją głowę.>', 0),
(4263, 'koKR', 'Czy ten nikczemnik nie żyje??', 0),
(4283, 'koKR', '<Oralius mówi do sporego, odciętego ogrzego ucha.>$B$BPłonące Stepy do centrali, zgłoś się, centrala.', 0),
(4286, 'koKR', 'Nie mam teraz czasu, $N. Ja i Winky mamy spotkanie.', 0),
(4296, 'koKR', 'Masz pisma Siedmiu, $N? $GPoznałeś:Poznałaś; tajemnice ich tablicy?', 0),
(4463, 'koKR', 'Przedstaw składniki, $gśmiertelniku:śmiertelniczko;.$B$BZa to dzieło zażądam też zapłaty w wysokości trzydziestu sztuk złota.', 0),
(4481, 'koKR', 'Za wszystko na tym świecie trzeba zapłacić. Ceną za przedmiot, którego szukasz, jest trzydzieści sztuk złota.$B$BRzecz jasna, większość zebranych przez ciebie składników zatrzymam. Ale nie martw się, dostaniesz swoją błyskotkę.', 0),
(4482, 'koKR', 'Trzydzieści sztuk złota. Trzydzieści sztuk złota i wymagane składniki.', 0),
(4483, 'koKR', 'Jeśli odporność jest tym, czego żądasz, trzydzieści sztuk złota mi dasz.', 0),
(4484, 'koKR', 'Nie marnuj mojego czasu. Daj mi to, czego wymagam. Trzydzieści sztuk złota i składniki.', 0),
(4701, 'koKR', 'Czy $godkryłeś:odkryłaś; źródło zagrożenia ze strony worgów i się z nim $grozprawiłeś:rozprawiłaś;?', 0),
(4726, 'koKR', 'Masz esencję smoczego młodego, $N? Nie mogę się doczekać, żeby ją zbadać.$B$BA poza tym... mój mecenas nie należy do osób, które chciałoby się rozczarować.', 0),
(4729, 'koKR', '<Kibler kłóci się właśnie z Tukanem Stanem.>', 0),
(4734, 'koKR', '$N, $gprzetestowałeś:przetestowałaś; jajoscyloskop?', 0),
(4735, 'koKR', 'Masz jaja, $N? Mój mecenas słyszał, że je dla mnie zbierasz, i bardzo chce dostać je w swoje ręce!', 0),
(4764, 'koKR', 'Masz klamrę, $N? Mój mecenas zapłaci za nią bardzo hojnie.', 0),
(4808, 'koKR', 'Zimno tu na górze! Mam nadzieję, że $gprzyniosłeś:przyniosłaś; mi koc!', 0),
(4810, 'koKR', '$N! $GRozmawiałeś:Rozmawiałaś; z Felnokiem? $GPrzyniosłeś:Przyniosłaś; części, których potrzebuję?', 0),
(4862, 'koKR', 'Masz w plecaku te pajęcze jaja, czy po prostu tak się cieszysz na mój widok?', 0),
(4866, 'koKR', '<Obdarty John cię szczypie.>', 0),
(5002, 'koKR', 'Ach, $N. Dawno się nie widzieliśmy.', 0),
(5081, 'koKR', 'Meldunek?', 0),
(5089, 'koKR', 'Co tam masz, $N?', 0),
(5262, 'koKR', 'Co tam masz, $N?', 0),
(5522, 'koKR', 'To ty rozrabiasz w Iglicy Czarnej Góry, prawda? Masz to, o co prosiłem?', 0),
(7487, 'koKR', 'Zanim otrzymasz dostęp, musisz dostroić swoją duszę do Ognistej Czeluści.', 0),
(7563, 'koKR', '$GWidziałeś:Widziałaś; rozwścieczone sowostwory, $N? Magia tych stworzeń jest silna i skupia się we krwi, która płynie w ich udręczonych ciałach.', 0),
(7564, 'koKR', 'Masz coś dla mnie? To chyba nie jest wielki, soczysty pająk? A może karaluch? Mam nadzieję, że jeszcze żyje... Tak uwielbiam je gryźć, póki jeszcze żyją...', 0),
(7626, 'koKR', 'Masz te eliksiry, $N? Mor\'zul powiedział mi, że potrzebujesz Dzwonu Dethmoory, a do jego wykonania potrzeba mnóstwa mocy cienia!', 0),
(7627, 'koKR', 'Koło Czarnego Marszu niełatwo zrobić, a potrzeba do niego mnóstwa materiałów. $GZebrałeś:Zebrałaś; je już?', 0),
(7628, 'koKR', '$GPrzyniosłeś:Przyniosłaś; smocze łuski, $N? Nie chcę zaczynać świecy, dopóki ich nie dostanę... bo mógłbym wysadzić cały obóz!', 0),
(7629, 'koKR', '$GByłeś:Byłaś; już w Scholomancjum, $N? Czy chochlik nasycił już pergamin gwiezdnym pyłem?', 0),
(7630, 'koKR', 'Masz arkanit, $N? Gdy go dostanę, zrobię ci czarny magnetyt.', 0),
(7848, 'koKR', 'Zanim otrzymasz dostęp, musisz dostroić swoją duszę do Ognistej Czeluści.', 0),
(8961, 'koKR', 'To było nasze szaleństwo... nasza zguba, że przyjęliśmy to ostatnie zlecenie. Gdybyśmy tylko nieświadomie nie ukradli ducha lorda Valthalaka zamkniętego w amulecie; gdyby tylko w naszej grupie najemników nie było tych, którzy byli tak chciwi, że podzielili go między siebie. Żyłbym dziś, może łykając piwko albo podrzucając w górę któreś z moich dzieci.$B$B$N, nie pozwól, by chciwość nikczemników z naszej dawnej kompanii najemników stała się i twoją zgubą.', 0),
(8962, 'koKR', 'Czyżbyś już $gwrócił:wróciła; z tym, po co cię posłałem, $N?', 0),
(8963, 'koKR', 'Czyżbyś już $gwrócił:wróciła; z tym, po co cię posłałem, $N?', 0),
(8964, 'koKR', 'Czyżbyś już $gwrócił:wróciła; z tym, po co cię posłałem, $N?', 0),
(8965, 'koKR', 'Czyżbyś już $gwrócił:wróciła; z tym, po co cię posłałem, $N?', 0),
(8966, 'koKR', 'A więc stało się? $GOdzyskałeś:Odzyskałaś; lewą część amuletu lorda Valthalaka i w końcu $gpozwoliłeś:pozwoliłaś; spocząć duchowi mojego starego towarzysza, Mora Szarego Kopyta?', 0),
(8967, 'koKR', 'Chyba nie $gzająłeś:zajęłaś; się już ocaleniem ducha Isalien i odzyskaniem lewej części amuletu lorda Valthalaka, $N?', 0),
(8968, 'koKR', 'Czy to znaczy, $N, że już $gpozwoliłeś:pozwoliłaś; spocząć duszom tych dwojga głupców i $godzyskałeś:odzyskałaś; lewą część amuletu lorda Valthalaka?', 0),
(8969, 'koKR', 'Chwała ci, $N, jeśli $gwróciłeś:wróciłaś; z lewą częścią amuletu. Jeśli jednak nie, to proszę, zajmij się tym, bo zapewniam cię, nie ma czasu do stracenia!', 0),
(8985, 'koKR', 'Czyżbyś już $gwrócił:wróciła; z tym, po co cię posłałem, $N?', 0),
(8986, 'koKR', 'Czyżbyś już $gwrócił:wróciła; z tym, po co cię posłałem, $N?', 0),
(8987, 'koKR', 'Czyżbyś już $gwrócił:wróciła; z tym, po co cię posłałem, $N?', 0),
(8988, 'koKR', 'Czyżbyś już $gwrócił:wróciła; z tym, po co cię posłałem, $N?', 0),
(8989, 'koKR', 'A więc stało się? $GOdzyskałeś:Odzyskałaś; prawą część amuletu lorda Valthalaka, $gscaliłeś:scaliłaś; amulet w całość i w końcu $gpozwoliłeś:pozwoliłaś; spocząć duchowi mojego starego towarzysza, Mora Szarego Kopyta?', 0),
(8990, 'koKR', 'Chyba nie $gzająłeś:zajęłaś; się już ocaleniem ducha Isalien i odzyskaniem prawej części amuletu lorda Valthalaka, $N? Pamiętaj, by połączyć części amuletu, zanim mi go oddasz.', 0),
(8991, 'koKR', 'Czy to znaczy, $N, że już $gpozwoliłeś:pozwoliłaś; spocząć duszom tych dwojga głupców i $gpołączyłeś:połączyłaś; części amuletu lorda Valthalaka?', 0),
(8992, 'koKR', 'Chwała ci, $N, jeśli $gwróciłeś:wróciłaś; z całym amuletem. Jeśli jednak nie, to proszę, zajmij się tym, bo zapewniam cię, nie ma czasu do stracenia!', 0),
(8994, 'koKR', 'Przeszliśmy długą drogę, $N, i chciałem tylko powiedzieć, że cokolwiek się stanie – dziękuję! $GNarażałeś:Narażałaś; życie, by pomóc ocalałym członkom naszej kompanii najemników, Zasłoniętego Ostrza, i jak dla mnie jesteś teraz $gjednym:jedną; z nas.', 0),
(8995, 'koKR', '$N, śmiesz zakłócać mój spoczynek!', 0),
(8996, 'koKR', '$N, $gwróciłeś:wróciłaś; i wciąż żyjesz! Cóż, przynajmniej jedno z nas żyje.$B$BMusisz mi o wszystkim opowiedzieć!', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
