(9536, 0, 'koKR', 'Pogoń za bogactwem to jedyny cel szanującego się goblina.$B$BNo, może bogactwo... i wielka, głośna śmierć!', 0),
(9562, 0, 'koKR', 'Witaj, $N.', 0),
(10260, 0, 'koKR', 'Witaj w Egzotycznych zwierzakach Kiblera! Jak możesz mi dziś pomóc??', 0);
