(22046, 'koKR', 'Prawa część amuletu lorda Valthalaka', 'Ta część amuletu drży wyczuwalnym pragnieniem, by znów połączyć się z pozostałymi częściami.', 0),
(22048, 'koKR', 'Amulet lorda Valthalaka', 'Scalony w całość amulet silnie pulsuje złym duchem lorda Valthalaka.', 0),
