INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(1471, 'koKR', 'Solomonie,$B$Bokaziciel tego dekretu otrzymał oficjalny status pełniącego obowiązki zastępcy Wichrogrodu. Możesz powierzyć tej osobie zadanie znalezienia dowodów na powiązania Czarnego Stada z orkami Czarnej Skały. Jeśli takie dowody zostaną znalezione, zastępca ma je dostarczyć mnie do Wichrogrodu, a wówczas wydam rozkaz wysłania sił zbrojnych wystarczających, by wesprzeć Jezierne Włości.$B$BZ poważaniem$B$B$B$BNajwyższy lord Bolvar Fordragon', 0),
(1691, 'koKR', 'Cześć, Felnoku!$B$BMoje badania na Płonących Stepach idą znakomicie. I wiele zawdzięczam $N za całą $gjego:jej; pomoc! Oto, czego potrzebuję, żeby kontynuować:$B$BStalospiralny bumber-bitzel$BLodoklucz kaliber 17$B12 funtów kaczego pierza$BSłoik tego kleju, który robisz$B$BWielkie dzięki, Felnoku, a gdy znów się zobaczymy, przypomnij mi, żebym nie wsypywała ci węgla do butów!$B$B– Tinkee', 0),
(2691, 'koKR', 'Aby spętać upiornego rumaka, musisz zrobić trzy rzeczy:$B$BStworzyć Krąg Większego Przywołania.$B$BWewnątrz Kręgu otworzyć portal do Xoroth i przeciągnąć przez niego upiornego rumaka.$B$BPokonać upiornego rumaka, a następnie podporządkować sobie jego ducha.$B$BNa kolejnych stronach szczegółowo opisuję, jak wykonać każdy z tych kroków. Nie będzie łatwo, ale $gokazałeś:okazałaś; się bardzo $gzdolny:zdolna;. Przy skupieniu i biegłości jestem pewien, że upiorny rumak będzie twój.$B$BCzytaj dalej,$B– Mor\'zul Zwiastun Krwi', 0),
(2692, 'koKR', 'Narzędzia rytuału$B$BZanim przystąpisz do zadania, musisz mieć następujące magiczne narzędzia:$B$BSłoik J\'eevee$BCzarny magnetyt$BKsorotiańskie glify$B$BMój sługa Gorzeeki przygotuje je dla ciebie, za opłatą. Nie próbuj wykonywać żadnego kroku rytuału bez wszystkich tych narzędzi. Każde z nich jest niezbędne.$B$BNa kolejnych stronach opiszę, jak należy używać każdego z narzędzi.', 0),
(2693, 'koKR', 'Krąg Większego Spętania$B$BKrąg Większego Spętania należy stworzyć w miejscu, gdzie magia jest silna. Takie miejsce znajduje się głęboko w ruinach Eldre\'Thalas, zwanych też Srogomłotami. W Eldre\'Thalas uwięziona jest istota wielkiej mocy, Immol\'thar; to na piedestale jego więzienia musisz odprawić rytuał tworzenia Kręgu.$B$BPrzebij się do piedestału, a potem wypuść J\'eevee ze słoika.', 0),
(2694, 'koKR', 'Dzwon, Koło i Świeca$B$BPo uwolnieniu J\'eevee ustawi on Dzwon, Koło i Świecę, a wtedy pojawi się krąg. To początek rytuału. Musisz zachować czujność; wspomniane przedmioty przewodzą ogromne energie i łatwo zawodzą. Gdy tak się stanie, musisz szybko użyć czarnego magnetytu, by je ponownie uruchomić, zanim cały rytuał się nie powiedzie.$B$BJeśli wszystkie trzy przedmioty zawiodą, zanim zdążysz je ponownie uruchomić, rytuał się kończy i trzeba zacząć go od nowa.', 0),
(2695, 'koKR', 'Poza przewodzeniem energii rytuału Dzwon, Koło i Świeca mają też własne, wyjątkowe właściwości.$B$BDzwon Dethmoory, gdy dzwoni, obdarza czarnoksiężników w kręgu wigorem i energią.$B$BKoło Czarnego Marszu, gdy się obraca, chroni przebywających w kręgu przed krzywdą.$B$BŚwieca zagłady, gdy płonie, ciska niesamowitą energią we wrogów wkraczających do kręgu.$B$BZe względu na te dobrodziejstwa bardzo ważne jest, by podczas rytuału wszystkie te przedmioty działały.', 0),
(2696, 'koKR', 'Należy też zaznaczyć, że czarny magnetyt, którym ponownie uruchamia się Dzwon, Koło lub Świecę, gdy zawiodą, wymaga odłamków dusz. Przy każdym ponownym uruchomieniu przedmiotu rytualnego magnetytem zużywany jest jeden z twoich odłamków dusz, więc przed rozpoczęciem rytuału zadbaj o ich spory zapas.', 0),
(2697, 'koKR', 'Dokończenie rytuału$B$BPostępy możesz śledzić po magicznych runach wzdłuż krawędzi kręgu. Gdy pojawi się dziewięć run, rytuał jest zakończony i zobaczysz energię wznoszącą się z nowo wzmocnionego Kręgu.$B$BWtedy możesz przywołać ksorotiańskie glify, otworzyć portal do Xoroth i przeciągnąć przez niego upiornego rumaka.$B$BPokonaj upiornego rumaka i uwolnij jego ducha. Stań przed duchem, a zostanie ci podporządkowany, ty zaś w nagrodę poznasz sekret jego przywoływania.', 0),
(2859, 'koKR', '<HTML><BODY><H1 align="center">KOSZ ŻAROWY INWOKACJI: INSTRUKCJA OBSŁUGI</H1><BR/><P align="center">Gdzie znaleźć nawiedzone miejsca</P><BR/><P align="center">WSTĘP</P><BR/><P align="left">Na tych stronach zawarto położenie poległych i spaczonych duchów i dusz związanych z incydentem z amuletem lorda Valthalaka. Choć $guratowałeś:uratowałaś; już tych moich dawnych towarzyszy, przypuszczam, że w owych nawiedzonych miejscach wciąż pobrzmiewają odrażające echa zła, które niegdyś wypaczyło ich dusze. Tak wielka była złowroga moc ducha lorda Valthalaka.</P><BR/><P align="left">Ponadto kosza żarowego można użyć, by przywołać lorda Valthalaka, choć tak jak poprzednio należy przy tym zachować najwyższą ostrożność.</P><BR/></BODY></HTML>', 0),
(2860, 'koKR', '<HTML><BODY><H1 align="center">WSTĘP, ciąg dalszy...</H1><BR/><P align="left">Sam kosz żarowy działa tak samo jak kosz żarowy przywołania. Wystarczy ustawić go w zasięgu któregokolwiek z pięciu nawiedzonych miejsc, a przywoła duchy zmarłych.</P><BR/><P align="left">Na marginesie, bo wiem, że cię to zainteresuje: sztandaru prowokacji można w podobny sposób użyć na arenie w Otchłani Czarnej Góry. Kiedy tylko tam będziesz, nie przepuść okazji, by dać nauczkę Theldrenowi i jego zbirom ode mnie.</P><BR/><P align="left">Czytaj dalej, jeśli pragniesz dalszego oświecenia.</P><BR/></BODY></HTML>', 0),
(2861, 'koKR', '<HTML><BODY><H1 align="center">ISALIEN</H1><BR/><P align="center">Nocnoelfia kapłanka księżyca</P><BR/><P align="left">Gdy Isalien postanowiła odejść z kompanii, zrobiła to z zamiarem odbycia pielgrzymki do Srogomłotów, upadłego miasta przodków nocnych elfów, znanego niegdyś jako Eldre\'Thalas. Wciąż stoi tam biblioteka wielkiej wiedzy – sanktuarium, w którym garstce nocnych elfów udało się powstrzymać napór wrogów. Chciała znaleźć odpowiedzi dotyczące swojego dziedzictwa, a być może także części amuletu. Warto zaznaczyć, że była też dobrą przyjaciółką Falrina Kształtującego Drzewa.</P><BR/></BODY></HTML>', 0),
(2862, 'koKR', '<HTML><BODY><H1 align="center">ISALIEN, ciąg dalszy...</H1><BR/><P align="left">Niestety, gdy wraz ze swoim towarzyszem, hipogryfem Empyreanem, wkraczała do miasta, napadł na nich Alzzin Kształtujący Dzicz ze swoimi sługami. Tam poległa, by nigdy już nie powstać. Być może to i lepiej, że Isalien nie odkryła więcej sekretów złej magii, którą lord Valthalak zamknął część swojej esencji w amulecie.</P><BR/><P align="left">Komnata pod gołym niebem, w której przebywa Alzzin, jest jednym z tych nawiedzonych miejsc.</P><BR/></BODY></HTML>', 0),
(2863, 'koKR', '<HTML><BODY><H1 align="center">MOR SZARE KOPYTO</H1><BR/><P align="center">Taureński druid, pierwszy, który poległ</P><BR/><P align="left">Mor Szare Kopyto zawsze był niezłomnym i zaufanym towarzyszem w Zasłoniętym Ostrzu. Szkoda, że jako pierwszy padł ofiarą złych sług lorda Valthalaka.</P><BR/><P align="left">Gdy uciekaliśmy przed Valthalakiem, ścigała nas istna armia jego widmowych zabójców i tropicieli. Ucieczka z Iglicy Czarnej Góry była, delikatnie mówiąc, chaotyczna. Niestety, po drodze Mor jakoś stracił równowagę, choć podejrzewam, że ktoś go popchnął. Tak czy inaczej, spadł w czeluście dolnej części iglicy.</P><BR/></BODY></HTML>', 0),
(2864, 'koKR', '<HTML><BODY><H1 align="center">MOR SZARE KOPYTO, ciąg dalszy...</H1><BR/><P align="left">Później dowiedzieliśmy się, że Mor przeżył upadek. Ale mojego dobrego przyjaciela nie czekało szczęśliwe zakończenie; trafił do niewoli trolli z Tazz\'Alaor. Niedługo potem, gdy torturował go Mistrz Wojenny Wun, grupa zabójców Valthalaka wpadła tam i dokończyła dzieła.</P><BR/><P align="left">Jeśli chcesz przywołać echo ducha Mora Szarego Kopyta, komnata Mistrza Wojennego Wuna jest nawiedzonym miejscem.</P><BR/></BODY></HTML>', 0),
(2865, 'koKR', '<HTML><BODY><H1 align="center">JARIEN I SOTHOS</H1><BR/><P align="center">Rodzeństwo i niedoszli członkowie Szkarłatnej Krucjaty</P><BR/><P align="left">Jarien i Sothos należeli do najbardziej nietolerancyjnych ludzi, jakich znałem. Jako wojownicy mieli jednak wyjątkowe umiejętności i pochodzili z bogatej rodziny, co pewnie tłumaczy, dlaczego Anthion, przywódca Zasłoniętego Ostrza, trzymał ich przy sobie.</P><BR/><P align="left">Rodzeństwo w końcu zachwyciło się naukami i filozofią Szkarłatnej Krucjaty. Zawsze wykazywali szczególną gorliwość w tępieniu wszelkich sług Plagi, na których natykaliśmy się w podróżach, i podejrzewano, że ich rodzina ma powiązania z tą organizacją.</P><BR/></BODY></HTML>', 0),
(2866, 'koKR', '<HTML><BODY><H1 align="center">JARIEN I SOTHOS, ciąg dalszy...</H1><BR/><P align="left">I tak stanęli przed próbami, jakie muszą przejść chętni do wstąpienia do Krucjaty. Szczególnie interesował ich stopień rycerski; do tego najwyraźniej trzeba było przejść trudniejsze próby. Później wyszło bowiem na jaw, że Sothos nie przeszedł ostatniej próby. Jarien nie chciała się jednak z tym pogodzić i w otwartym buncie zażądała, by mógł dołączyć do niej w szeregach rycerzy. Z tego, co ustaliliśmy, Wielki Krzyżowiec Dathrohan zabił ich oboje na miejscu, pośrodku swojej komnaty.</P><BR/><P align="left">Tak oto kolejnym z nawiedzonych miejsc jest Karmazynowy Tron w Szkarłatnym Bastionie w Stratholmie.</P><BR/></BODY></HTML>', 0),
(2867, 'koKR', '<HTML><BODY><H1 align="center">KORMOK</H1><BR/><P align="center">Dwugłowy ogrzy nekromanta</P><BR/><P align="left">Cóż można powiedzieć o Kormoku? Był dwugłowym ogrem z tych rzucających czary i kiedyś nie był wcale taki zły. Gdy pierwszy raz przyjęliśmy go do grona, był jeńcem przy jakimś zleceniu, którego podjęliśmy się na Płonących Stepach. Okazał się jednak nieoceniony, pomagając nam wyrwać się z kłopotliwego położenia, w które tam wpadliśmy, więc dołączył do kompanii jako jeden z jej najlepszych magów.</P><BR/><P align="left">Dziwne było w nim jednak to, że jego dwie głowy miały zupełnie odmienną naturę. Jedna była zawsze wesoła, choć nieco głupkowata, druga zaś chytra, wyrachowana i o niemal martwym spojrzeniu. Doprawdy trochę upiorne.</P><BR/></BODY></HTML>', 0),
(2868, 'koKR', '<HTML><BODY><H1 align="center">KORMOK, ciąg dalszy...</H1><BR/><P align="left">Później, podczas naszych podróży, Kormok zetknął się z nekromantyczną stroną magii. Niestety, upiorna głowa wykazała talent do wskrzeszania duchów zmarłych i czerpała z tego perwersyjną przyjemność, zwłaszcza z przywoływania wygnanych duchów z Wyspy Oczyszczenia, by spełniały jego rozkazy.</P><BR/><P align="left">Po rozwiązaniu kompanii Kormok zapisał się do Scholomancjum, by kontynuować „edukację”. Widmowi zabójcy aż nazbyt łatwo dostali się do szkoły i zabili go tam, na oczach jego nowego mistrza, Reza Szeptu Mrozu.</P><BR/><P align="left">Przez to komnata Reza Szeptu Mrozu jest jednym z nawiedzonych miejsc, w których można skutecznie użyć kosza żarowego.</P><BR/></BODY></HTML>', 0),
(2869, 'koKR', '<HTML><BODY><H1 align="center">LORD VALTHALAK</H1><BR/><P align="center">Drakoński szlachcic i dawny generał Iglicy Czarnej Góry</P><BR/><P align="left">Przed generałem Drakkisatem był lord Valthalak, drakoński czarnoksiężnik o ogromnej mocy. Władza w Iglicy często przechodzi z rąk do rąk i, niestety dla nas, mieliśmy odegrać rolę w ostatniej zmianie władzy.</P><BR/><P align="left">Zlecenie kradzieży księgi zaklęć Valthalaka dał nam goblin, przemytnik i czarodziej z Łupieżczej Zatoki, Gremnik Rizzlesprang. Nie wiemy, czy chciał ją studiować, czy sprzedać (czy jedno i drugie),\n i teraz nie ma to znaczenia. Ważne, że zakradliśmy się do górnych partii Iglicy Czarnej Góry i zabiliśmy lorda Valthalaka w jego leżu. Wtedy dopiero zaczęła się zabawa.</P><BR/></BODY></HTML>', 0),
(2870, 'koKR', '<HTML><BODY><H1 align="center">LORD VALTHALAK, ciąg dalszy...</H1><BR/><P align="left">Nie mieliśmy pojęcia, jak głęboka jest wiedza magiczna Valthalaka w zakresie manipulowania duszami, bo inaczej pewnie nigdy nie przyjęlibyśmy tego zlecenia. Ale przyjęliśmy i okazało się ono ostatnim, jakiego się podjęliśmy.</P><BR/><P align="left">Gdy zabiliśmy lorda Valthalaka i zabraliśmy jego księgę zaklęć, Kormok musiał coś wyczuć w jego amulecie. Uparł się, że weźmie go jako swoją część łupu, co szybko przerodziło się w zażartą kłótnię, a niemal i bójkę o ten przedmiot. Nie wiedzieliśmy wtedy, że w amulecie mieści się spora część ducha Valthalaka; przekonaliśmy się o tym później, ku naszemu niezadowoleniu.</P><BR/></BODY></HTML>', 0),
(2871, 'koKR', '<HTML><BODY><H1 align="center">LORD VALTHALAK, ciąg dalszy...</H1><BR/><P align="left">Podzieliwszy amulet na części, uciekliśmy przed świeżo powstałym duchem Valthalaka i jego armią widmowych zabójców. A hałas, jaki narobiliśmy, kłócąc się o amulet, zbudził wielu pozostałych obrońców Iglicy!</P><BR/><P align="left">Niemal wszyscy wydostaliśmy się z Czarnej Góry i myśleliśmy, że jesteśmy bezpieczni. Ale nawet zza grobu Valthalak nasyłał na nas swoje sługi, gdziekolwiek byśmy się ukryli. Wkrótce po tej misji Zasłonięte Ostrze się rozpadło, a wtedy staliśmy się naprawdę łatwym łupem.</P><BR/><P align="left">Jak już zapewne wiesz, przez to siedziba lorda Valthalaka, obecnie komnata Bestii w Iglicy Czarnej Góry, jest ostatnim z nawiedzonych miejsc.</P><BR/></BODY></HTML>', 0);
INSERT INTO `gossip_menu_option_locale` (`MenuID`, `OptionID`, `Locale`, `OptionText`, `BoxText`) VALUES
(6001, 0, 'koKR', '<Kładę dłoń na kuli.>', '');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(4594, 'koKR', 'Opuść to miejsce. <Z relikwii wystrzeliwuje rozżarzony do białości łuk płomienia. Zyskujesz wspomnienie: samotny krasnolud z Czarnorytych, otoczony siedmioma trupami, klęczy przed monolitem z płomieni.>', '', 0),
(4595, 'koKR', 'Zginiesz tutaj. <Twój umysł wypełniają wizje chaosu i zniszczenia.>', '', 0),
(4596, 'koKR', 'Nie kalaj tych ruin, $gśmiertelniku:śmiertelniczko;. <Ogarnia cię oślepiający błysk światła. Jedyne, co pamiętasz, to istota złożona wyłącznie z płomieni.>', '', 0),
(4597, 'koKR', 'Pomóż nam, $gprzybyszu:przybyszko;. <Relikwia rozsypuje się w proch. Twoją głowę wypełnia wizja ośmiu krasnoludów z Czarnorytych odprawiających jakiś rytuał.>', '', 0),
(4598, 'koKR', 'Nie można go pokonać. <Relikwia spala się na nic. Wspomnienia, które w sobie kryła, są teraz twoje. To miasto zniszczyła istota nie z tego świata.>', '', 0),
(4599, 'koKR', 'Twoje istnienie zostało zauważone. <Relikwia obraca się w proch. W głowie pulsuje ci nowo zdobyta mądrość. W sercu góry czai się coś złego.>', '', 0),
(4600, 'koKR', '$gBezcześcicielu:Bezcześcicielko;... zostaniesz $gukarany:ukarana; za to wtargnięcie. <Z relikwii promieniuje symbol płomienia, po czym rozsypuje się ona w ziemię.>', '', 0),
(4646, 'koKR', 'Witaj, $N. Jestem Franclorn Kuźnomistrz. Czy przybywasz, by dowiedzieć się czegoś o Iglicy i o Czarnorytych?', '', 0),
(4648, 'koKR', 'Niesamowite! Nigdy nie $grozmawiałem:rozmawiałam; z duchem. Chcę się dowiedzieć!', 'Niesamowite! Nigdy nie $grozmawiałem:rozmawiałam; z duchem. Chcę się dowiedzieć!', 0),
(4649, 'koKR', 'Nie miałem wyboru, a przynajmniej tak mi się zdawało. Miałem przetrwać zniszczenie Thaurissana i stać u boku mojego króla i jego ludu.$B$BPod władzą Ragnarosa król Dagran Thaurissan wydarł serce tej góry i wzniósł Iglicę Czarnej Góry. Pracowaliśmy niestrudzenie, by zbudować krasnoludzkie miasto potężniejsze niż jakiekolwiek miasto czy twierdza, które powstały przed nim... lub miały powstać po nim.', '', 0),
(4651, 'koKR', 'Stałem z boku i patrzyłem, jak zepsucie Ragnarosa sączy się do serc i umysłów narodu Czarnorytych. Niegdyś honorowa rasa, doprowadzona do szaleństwa... do zła.$B$BGdy budowa Iglicy dobiegła końca, moja wola życia wśród mojego ludu osłabła. Odszedłem jako bohater nowego narodu Czarnorytych. Ten grobowiec umieszczono tutaj – u wejścia do miasta, które zaprojektowałem i zbudowałem – w uznaniu moich zasług.', '', 0),
(4652, 'koKR', 'Fascynujące. Proszę, opowiedz mi więcej.', 'Fascynujące. Proszę, opowiedz mi więcej.', 0),
(4653, 'koKR', 'Mój wielki młot, Żelazospacz, przekazano nowemu głównemu architektowi, Fineousowi Mrokowijowi: człowiekowi o nikczemnych pobudkach i marnym talencie.$B$BTu wkraczasz ty, $N. Chcę, żeby ktoś go powstrzymał. Jest zbyt nieudolny, by okiełznać prawdziwą moc Żelazospacza, ale gdyby po nim przyszedł ktoś zdolny wykorzystać pełnię potencjału Żelazospacza, zniszczenia, jakie mógłby wywołać swoimi dziełami, byłyby katastrofalne dla tego świata.', '', 0),
(4654, 'koKR', 'Po prostu wskaż mi drogę, Franclornie.', 'Po prostu wskaż mi drogę, Franclornie.', 0),
(4655, 'koKR', 'Fineousa Mrokowija znajdziesz za Kręgiem Prawa, w Sali Rzemiosła. Zabij tego nędznego kundla i odzyskaj Żelazospacza.$B$BZanieś Żelazospacza do Kaplicy Thaurissana i umieść młot tam, gdzie jego miejsce: w dłoniach posągu wzniesionego na moją cześć.$B$BGdy to zrobisz, otworzy się skrytka, w której ukryłem klucz główny. Co ważniejsze, Żelazospacz na zawsze pozostanie w moim uścisku. Jeśli spróbują wyjąć młot, zarówno posąg, jak i młot roztrzaskają się i przepadną na zawsze.', '', 0),
(4707, 'koKR', 'GOR\'TESH NIE ŻYJE?!?!', '', 0),
(4708, 'koKR', 'UCIEKAĆ! UCIEKAĆ NA WZGÓRZA!', '', 0),
(4709, 'koKR', 'KTO ZABIĆ GOR\'TESH!?!? KTO TO ZROBIĆ?!', '', 0),
(4711, 'koKR', '$n ZABIĆ! $GOn:Ona; zabić was teraz! UCIEKAĆ! UCIEKAĆ!', '', 0),
(4712, 'koKR', 'Uciekać na wzgórza! Czekać! My już na wzgórza!', '', 0),
(4753, 'koKR', 'Tylko głupiec śmiałby niepokoić mnie w moim leżu.', '', 0),
(4754, 'koKR', 'Przedstawiam ci dowód moich czynów, Cyrusie.', 'Przedstawiam ci dowód moich czynów, Cyrusie.', 0),
(4755, 'koKR', 'Nie mam żadnego dowodu, Cyrusie.', 'Nie mam żadnego dowodu, Cyrusie.', 0),
(4756, 'koKR', '<Oczy Cyrusa jasno rozbłyskują>$B$BMam cię pożreć w całości czy pozwolić ci żyć?$B$BByć może jeszcze się na coś przydasz...$B$BZmierz się z moim sługą, $N. Przeżyj i przynieś mi dowód swojego zwycięstwa.', '', 0),
(4759, 'koKR', 'Jestem $ggotów:gotowa;!', 'Jestem $ggotów:gotowa;!', 0),
(5006, 'koKR', 'Czego chcesz? *hik*', '', 0),
(5177, 'koKR', 'Przepisz tablicę.', 'Przepisz tablicę.', 0),
(5178, 'koKR', 'Starannie przepisujesz symbole z tablicy...', '', 0),
(5246, 'koKR', 'Szczątki pokrywają muchy i czerwie.', '', 0),
(5290, 'koKR', 'Przepadły, $N. Libramy spisane przez elfich mistrzów. Rozproszone po świecie, gdy Plaga została spuszczona na Quel\'Thalas.$B$BTeraz szukamy tych libramów. Szukamy, by poznać skrywane w nich sekrety – by przywrócić moc, którą niegdyś mieliśmy.$B$BJa szukam dziesięciu spisanych przez mistrza Kariela Winthalusa. Jeśli znajdziesz libram, pozwól mi wchłonąć jego magiczne właściwości, a wykonam dla ciebie amalgamat mocy... oczywiście wszystko ma swoją cenę. Moja cena wyda ci się wysoka, ale zapłacisz ją.', '', 0),
(5291, 'koKR', 'Przedstawiam ci libram rozmyślań.', 'Przedstawiam ci libram rozmyślań.', 0),
(5292, 'koKR', 'Ach, więc... $gznalazłeś:znalazłaś; go.$B$B<Mathredis wskazuje na księgę, którą masz przy sobie.>$B$B$GZebrałeś:Zebrałaś; potrzebne składniki?$B$BManifestacje wymienione w libramie, $gimbecylu:imbecylko;!', '', 0),
(5293, 'koKR', '<Mathredis wpatruje się uważnie w libram.>$B$BPrzychodzisz po amalgamat? $GZrobiłeś:Zrobiłaś; to, co nakazuje libram?', '', 0),
(5294, 'koKR', 'Daj mi arkanum, a wykonam amalgamat, $gśmiertelniku:śmiertelniczko;.', '', 0),
(5295, 'koKR', 'Doprawdy, rzadkie znalezisko.$B$B<Mathredis kiwa głową.>$B$BJeśli chcesz kontynuować, będę potrzebował składników.', '', 0),
(5296, 'koKR', 'Chciwość przywiodła cię z powrotem do mnie.$B$B<Mathredis się śmieje.>$B$BPewien mądry draenei powiedział mi kiedyś, że to właśnie chciwość jest jedyną cechą wspólną wszystkich ras tego świata. Muszę się z nim zgodzić.$B$B$GZebrałeś:Zebrałaś; składniki wymienione w libramie?', '', 0),
(5416, 'koKR', 'Przedstawiam ci libram kondycji.', 'Przedstawiam ci libram kondycji.', 0),
(5417, 'koKR', 'Przedstawiam ci libram nieustępliwości.', 'Przedstawiam ci libram nieustępliwości.', 0),
(5418, 'koKR', 'Przedstawiam ci libram odporności.', 'Przedstawiam ci libram odporności.', 0),
(5419, 'koKR', 'Przedstawiam ci libram żarłoczności.', 'Przedstawiam ci libram żarłoczności.', 0),
(5539, 'koKR', 'SKRZEK!! *kaszle* *kaszle* Muszę rzucić palenie!', '', 0),
(5540, 'koKR', 'Zapytaj Kiblera o skarb! SKRZEK!', '', 0),
(5541, 'koKR', 'Bijou zaginęła! SKRZEK! *kaszle*', '', 0),
(5542, 'koKR', 'Bijou wie, gdzie ukryte są skarby.', '', 0),
(5543, 'koKR', 'Opus chce trochę Złota Cuerga... z robakiem.', '', 0),
(5544, 'koKR', 'Wszyscy idą do Iglicy, ale nikt nigdy nie wraca... tak jak Bijou.', '', 0),
(5545, 'koKR', 'Kiblerem zajmuje się T.E.P.L.', '', 0),
(5546, 'koKR', 'Smoki rządzą orkami!? SKRZEK!', '', 0),
(5552, 'koKR', '', 'Płonące Stepy to niebezpieczne miejsce, ale uczeni tacy jak ja zrobią niemal wszystko, by poszerzyć swoją wiedzę.', 0),
(5833, 'koKR', 'Wydój mnie, John.', 'Wydój mnie, John.', 0),
(5834, 'koKR', 'Z przyjemnością... tylko pozwól mi się nacieszyć tą chwilą jeszcze minutkę.', '', 0),
(5835, 'koKR', 'Zrób to... Zrób to teraz.', 'Zrób to... Zrób to teraz.', 0),
(9488, 'koKR', 'Tkanina, z której utkany jest nasz świat, jest niezwykle delikatna. Wystarczy odrobina wiedzy i umiejętność jej zastosowania, by ją rozedrzeć. Tak właśnie rodzą się szczeliny.', '', 0),
(9742, 'koKR', 'Skończyłem. Pergamin gotowy. Teraz wracaj do Gorzeekiego...', '', 0),
(9746, 'koKR', 'Lawa? Nie zwracaj na nią uwagi, $gprzyjacielu:przyjaciółko;. Rozejrzyj się. Rozkoszuj się radościami, jakie niesie natura.', '', 0),
(9754, 'koKR', 'Więc to ty jesteś Klinfran Obłąkany? Szkoda, $gliczyłem:liczyłam; na prawdziwe wyzwanie. Odważysz się stanąć do walki w swojej prawdziwej postaci?', 'Więc to ty jesteś Klinfran Obłąkany? Szkoda, $gliczyłem:liczyłam; na prawdziwe wyzwanie. Odważysz się stanąć do walki w swojej prawdziwej postaci?', 0),
(9769, 'koKR', 'Ach, jesteśmy na miejscu! No to bierzmy się do roboty, co...?', '', 0),
(9770, 'koKR', 'A, racja! Teraz tutaj...', '', 0),
(9771, 'koKR', 'A teraz... ostatni krok!', '', 0),
(9857, 'koKR', 'Na powierzchni kuli odciśnięty jest ślad dużej humanoidalnej dłoni. Choć kulę najwyraźniej bezustannie ktoś dotyka i przekłada, pozostaje nieskazitelna.', '', 0),
(9858, 'koKR', 'Oznaczenia na kuli pasują do piętna na twojej dłoni.', '', 0),
(11548, 'koKR', 'Gdzie jest Nestor Świtokrocz?', 'Gdzie jest Nestor Świtokrocz?', 0),
(11549, 'koKR', 'Nestor Świtokrocz przebywa na Płomiennym Grzbiecie na Płonących Stepach.', 'Nestor Świtokrocz przebywa na Płomiennym Grzbiecie na Płonących Stepach.', 0),
(11769, 'koKR', 'Do tej pory byłem dla was łagodny, ale teraz mnie nudzicie. Ujrzyjcie wspaniałość mojej potęgi i rozpaczajcie!', '', 0),
(11770, 'koKR', 'Nie zginę ponownie! Nie z ręki kogoś takiego jak wy!!', '', 0),
(11860, 'koKR', '', 'Moje męki dobiegły końca i teraz mogę dołączyć do Bogini. Dziękuję wam z całego serca!', 0),
(11861, 'koKR', 'Choć odchodzę w pokoju, macie moją dozgonną wdzięczność. Dziękuję, że uwolniliście mnie od klątwy mojej głupoty i chciwości.', '', 0),
(11873, 'koKR', 'My być wolni! Dzięki, mali, słabi.', '', 0),
(11939, 'koKR', '%s wpada w szał, widząc, jak $n pada w bitwie!', '%s wpada w szał, widząc, jak $n pada w bitwie!', 0),
(11955, 'koKR', 'Twoje zuchwalstwo jest odrażające, $ggłupcze:głupia;! Pożywię się twoją duszą!', '', 0),
(11959, 'koKR', 'Wy tacy mali i słabi... wy nie być dobre sługi dla Kormoka!', '', 0),
(11966, 'koKR', 'Cała potęga Natury jest na moje rozkazy, marni śmiertelnicy. Zobaczmy, która z moich wielu postaci zakończy wasze cierpienia!', '', 0),
(11967, 'koKR', 'Muahahahaha! Cóż to za żałosne widowisko rozgrywa się przede mną? No, na co czekacie? Jestem głodny, a wy wyglądacie na całkiem znośną przystawkę!', '', 0),
(11968, 'koKR', 'Wy myśleć, że móc nas przywołać? To my przywoływać, nie wy! My was dobrze za to zmiażdżyć i wyssać szpik z wasze kości!', '', 0),
(11971, 'koKR', '', 'Witaj, bracie.', 0),
(11972, 'koKR', 'Witaj, siostro. Co my tu mamy?', '', 0),
(11973, 'koKR', '', 'Obawiam się, że niedoszłych intruzów.', 0),
(11974, 'koKR', 'Czy zabijemy ich za zuchwałe zakłócenie naszego snu?', '', 0),
(11975, 'koKR', '', 'Tak, zabijemy!', 0),
(13491, 'koKR', 'Przenieś mnie do Ognistej Czeluści, Lothosie.', 'Przenieś mnie do Ognistej Czeluści, Lothosie.', 0);
